// ── Resultado por IA (regras do Painel) ──────────────────────
// Usadas pelo Dashboard e pelas abas Garanhões/Éguas, pra que a mesma
// IA conte igual em todas.

// CEs vinculadas a uma IA, com qualquer resultado (iaOrigemId OU
// heurística: mesma égua + CE em até 15 dias depois da IA). Base
// COMPLETA, não só do mês — a CE pode ter caído no mês seguinte.
function cesVinculadasDaIa(registros, ia) {
  return (registros || []).filter(r => {
    if (r.tipo !== 'transferencia_embriao') return false;
    if (r.dados?.iaOrigemId === ia.id) return true;
    if (r.eguaId !== ia.eguaId) return false;
    if (!r.data || !ia.data) return false;
    if (r.data < ia.data) return false;
    const dd = (new Date(r.data + 'T12:00:00') - new Date(ia.data + 'T12:00:00')) / 86400000;
    return dd >= 0 && dd <= 15;
  });
}

// DGs lançados como registro à parte (Diagnóstico de Gestação) da
// mesma égua, depois da IA e antes da próxima IA dela. É por aí que
// costuma entrar o DG12 da IA pra prenhez na própria égua.
function dgsSeparadosDaIa(registros, ia) {
  if (!ia.data) return [];
  const proximaIa = (registros || [])
    .filter(x => x.tipo === 'inseminacao_artificial' && x.eguaId === ia.eguaId && (x.data || '') > ia.data)
    .map(x => x.data)
    .sort()[0];
  return (registros || []).filter(r => r.tipo === 'diagnostico_gestacao'
    && r.eguaId === ia.eguaId
    && r.data && r.data >= ia.data
    && (!proximaIa || r.data < proximaIa)
    && (r.dados?.resultado === 'positivo' || r.dados?.resultado === 'negativo'));
}

// IA pra prenhez na própria égua: algum DG lançado / algum DG positivo
// (nos campos da própria IA ou em registro à parte).
const CAMPOS_DG_IA = ['dgInicial', 'dg15', 'dg45', 'dg60'];
function iaPrenhezTemDg(registros, ia) {
  const d = ia.dados || {};
  return CAMPOS_DG_IA.some(k => d[k] === 'positivo' || d[k] === 'negativo')
    || dgsSeparadosDaIa(registros, ia).length > 0;
}
function iaPrenhezPositiva(registros, ia) {
  const d = ia.dados || {};
  return CAMPOS_DG_IA.some(k => d[k] === 'positivo')
    || dgsSeparadosDaIa(registros, ia).some(dg => dg.dados.resultado === 'positivo');
}

// IA que já teve tempo de dar resultado — base justa das taxas. IA
// recente contada como "sem Embr+" derruba a taxa. Entram só:
//  - destino=transferencia: IA que já virou CE (positiva ou negativa)
//  - destino=prenhez (na própria égua): IA com DG lançado ou que já
//    chegou no D12 (dia do primeiro DG)
function iaResolvida(registros, ia, hojeIso) {
  const destino = ia.dados?.destino;
  if (destino === 'transferencia') return cesVinculadasDaIa(registros, ia).length > 0;
  if (destino === 'prenhez') {
    return iaPrenhezTemDg(registros, ia) || (!!ia.data && addDias(ia.data, 12) <= hojeIso);
  }
  return false;
}

// Embriões positivados de uma IA: TE soma os embriões das CEs+;
// prenhez na própria égua conta 1 se algum DG deu positivo.
function embrioesPosDaIa(registros, ia) {
  const destino = ia.dados?.destino;
  if (destino === 'transferencia') {
    return cesVinculadasDaIa(registros, ia)
      .filter(ce => ce.dados?.resultado === 'positivo')
      .reduce((soma, ce) => soma + Math.max(1, Number(ce.dados?.qtdEmbrioes) || 1), 0);
  }
  if (destino === 'prenhez') return iaPrenhezPositiva(registros, ia) ? 1 : 0;
  return 0;
}

// ── Dashboard ────────────────────────────────────────────────
function ReproDashboard({ registrosRepro, eguasRepro, vetsExternos, servicos = [], centraisRepro = [], currentUser }) {
  const hoje = new Date();
  // Default: mês mais recente com registros. Se não há registros, mês atual.
  const mesInicial = useMemo(() => {
    const datas = (registrosRepro || []).map(r => r.data).filter(Boolean).sort();
    if (datas.length === 0) return { mes: hoje.getMonth() + 1, ano: hoje.getFullYear() };
    const ultima = datas[datas.length - 1];
    const [y, m] = ultima.split('-');
    return { mes: Number(m), ano: Number(y) };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [mesRef, setMesRef] = useState(mesInicial);
  const [filtroVetId, setFiltroVetId] = useState('');
  const [todosMeses, setTodosMeses] = useState(false);
  // Lista detalhada que abre ao clicar nos cards de topo
  const [detalheAberto, setDetalheAberto] = useState(null); // 'ia' | 'ce' | 'dg' | 'sv' | null

  const emMes = (iso) => {
    if (!iso) return false;
    const [y, m] = iso.split('-');
    return Number(y) === mesRef.ano && Number(m) === mesRef.mes;
  };

  // Resolve a IA de origem de uma CE (preferência: iaOrigemId; fallback:
  // última IA da mesma égua com destino=transferencia nos 15 dias
  // anteriores). Usado pra atribuir CE/DG ao vet INSEMINADOR (quem
  // inseminou, não quem coletou — essa é a regra do negócio pra medir
  // sucesso reprodutivo).
  const todasIas = (registrosRepro || []).filter(r => r.tipo === 'inseminacao_artificial');
  const iaDeOrigem = (ce) => {
    if (ce.dados?.iaOrigemId) {
      return todasIas.find(ia => ia.id === ce.dados.iaOrigemId) || null;
    }
    const candidatas = todasIas
      .filter(ia => ia.eguaId === ce.eguaId
        && ia.dados?.destino === 'transferencia'
        && (ia.data || '') <= (ce.data || ''))
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''));
    for (const ia of candidatas) {
      if (!ia.data || !ce.data) continue;
      const diasDiff = (new Date(ce.data + 'T12:00:00') - new Date(ia.data + 'T12:00:00')) / 86400000;
      if (diasDiff <= 15) return ia;
    }
    return null;
  };
  const vetDaCe = (ce) => iaDeOrigem(ce)?.vetId || ce.vetId;

  // Base: tudo do mês (sem filtro de vet). Filtro de vet aplica de forma
  // diferente por métrica.
  //
  // REGRA CENTRAL: processos reprodutivos são atribuídos ao mês da IA
  // de origem. IA de setembro → CE/DGs dessa IA alimentam setembro
  // (mesmo que tenham acontecido em outubro). Assim o funil IA → Embr+
  // → Prenh. compara coisas do mesmo lote.
  // Exceções:
  //  - CF: usa o mês do próprio CF (manejo pré-IA, não tem IA vinculada)
  //  - SV: usa o mês do próprio registro
  const regsMes = (registrosRepro || []).filter(r => todosMeses || emMes(r.data));
  const regs = filtroVetId ? regsMes.filter(r => r.vetId === filtroVetId) : regsMes;

  const semDadosMes = !todosMeses && regs.length === 0;
  const totalRegistrosGlobal = (registrosRepro || []).length;

  // IAs do mês (filtro de vet executor = inseminador)
  const iasDoMes = regs.filter(r => r.tipo === 'inseminacao_artificial');
  const totalIA = iasDoMes.length;

  const cfsDoMes = regs.filter(r => r.tipo === 'controle_folicular');
  const totalCF = cfsDoMes.length;
  const svsDoMes = regs.filter(r => r.tipo === 'servico_avulso');

  // Separa IAs do mês por destino pros cálculos de Embr+ e Prenh.
  const iasPrenhez = iasDoMes.filter(r => r.dados?.destino === 'prenhez');
  const iasParaTe = iasDoMes.filter(r => r.dados?.destino === 'transferencia');

  // CEs+ vinculadas a uma IA (ver cesVinculadasDaIa)
  const encontraCesDaIa = (ia) => cesVinculadasDaIa(registrosRepro, ia).filter(r => r.dados?.resultado === 'positivo');

  // IAs já resolvidas — base do gráfico IA × Embr+ (ver iaResolvida)
  const hojeIso = hoje.toLocaleDateString('sv-SE');
  const totalIaResolvidas = iasDoMes.filter(ia => iaResolvida(registrosRepro, ia, hojeIso)).length;

  // CE do mês atribuídas (via mês da IA de origem). Usada só pelo
  // detalhe antigo; a métrica central é embrioesPosLinhas.
  const cesAtribuidas = [];
  for (const ia of iasParaTe) {
    for (const ce of encontraCesDaIa(ia)) cesAtribuidas.push(ce);
  }

  // ── Embriões positivados — ancorados ao mês da IA ─────────────
  // Pra cada IA do mês:
  //  - destino=transferencia: itera CE+ vinculadas, soma qtdEmbrioes
  //  - destino=prenhez: conta se tem algum DG positivo, na própria IA
  //    ou lançado à parte
  const embrioesPosLinhas = [];
  for (const ia of iasParaTe) {
    const ces = encontraCesDaIa(ia);
    for (const ce of ces) {
      const qtd = Math.max(1, Number(ce.dados?.qtdEmbrioes) || 1);
      for (let i = 0; i < qtd; i++) {
        embrioesPosLinhas.push({
          key: `${ce.id}:${i}`, tipo: 'ce', regId: ce.id, embIdx: i, qtd,
          cavaloId: ce.eguaId, data: ce.data,
          garanhao: ia.dados?.garanhao || ce.dados?.garanhao || '',
          iaData: ia.data,
          vetInseminador: ia.vetId,
        });
      }
    }
  }
  for (const ia of iasPrenhez) {
    const d = ia.dados || {};
    if (iaPrenhezPositiva(registrosRepro, ia)) {
      embrioesPosLinhas.push({
        key: `${ia.id}:0`, tipo: 'prenhez', regId: ia.id, embIdx: 0, qtd: 1,
        cavaloId: ia.eguaId, data: ia.data,
        garanhao: d.garanhao || '', iaData: ia.data,
        vetInseminador: ia.vetId,
      });
    }
  }
  const totalEmbrioesPos = embrioesPosLinhas.length;

  // ── Coletas de embrião feitas — ancoradas ao mês da IA ────────
  // Todas as CEs (positivas e negativas) vinculadas às IAs pra TE do
  // mês. 1 linha por coleta (não por embrião).
  const coletasLinhas = [];
  const cesVistas = new Set();
  for (const ia of iasParaTe) {
    for (const ce of cesVinculadasDaIa(registrosRepro, ia)) {
      if (cesVistas.has(ce.id)) continue;
      cesVistas.add(ce.id);
      coletasLinhas.push({
        key: ce.id, regId: ce.id, cavaloId: ce.eguaId, data: ce.data,
        garanhao: ia.dados?.garanhao || ce.dados?.garanhao || '',
        iaData: ia.data,
        resultado: ce.dados?.resultado || null,
        qtd: Math.max(1, Number(ce.dados?.qtdEmbrioes) || 1),
        vetInseminador: ia.vetId,
      });
    }
  }
  const totalColetas = coletasLinhas.length;
  const totalEmbrioesPosCe = embrioesPosLinhas.filter(l => l.tipo === 'ce').length;
  const totalEmbrioesPosPrenhez = embrioesPosLinhas.filter(l => l.tipo === 'prenhez').length;

  // ── Embriões que viraram DG15+ (sobrevivência inicial) ────────
  // Um gráfico por origem, cada um contra o Embr+ da mesma origem:
  // embriões de CE+ que positivaram na receptora e IAs pra prenhez
  // na própria égua. Conta como DG15+ qualquer DG positivo do D15 em
  // diante (não precisa ser exatamente no D15):
  //  - CE: na própria CE (dados.dgXX ou dgsEmbrioes[i].dgXX), OU na
  //    inovulação vinculada à CE via ceOrigemId
  //  - IA prenhez: dados.dg15/dg45/dg60 da própria IA (botões do painel
  //    de acompanhamento) OU DG+ lançado à parte a partir de 15 dias
  //    depois da IA
  const embrioesDg15Linhas = [];
  for (const ia of iasParaTe) {
    for (const ce of encontraCesDaIa(ia)) {
      const d = ce.dados || {};
      const qtd = Math.max(1, Number(d.qtdEmbrioes) || 1);
      const dgsArr = Array.isArray(d.dgsEmbrioes) ? d.dgsEmbrioes : [];
      const inovsDaCe = (registrosRepro || []).filter(r =>
        r.tipo === 'inovulacao_embriao' && r.dados?.ceOrigemId === ce.id);
      for (let i = 0; i < qtd; i++) {
        const emb = (qtd === 1 && dgsArr.length === 0)
          ? { dg15: d.dg15 || null, dg30: d.dg30 || null, dg45: d.dg45 || null, dg60: d.dg60 || null }
          : (dgsArr[i] || {});
        // DG+ do D15 em diante marcado na CE OU em alguma inovulação linkada
        const dg15DaCe = ['dg15', 'dg30', 'dg45', 'dg60'].some(k => emb[k] === 'positivo');
        const dg15DaInov = inovsDaCe.some(iv => ['dg15', 'dg25', 'dg45', 'dg60'].some(k => iv.dados?.[k] === 'positivo'));
        if (dg15DaCe || dg15DaInov) {
          embrioesDg15Linhas.push({
            key: `${ce.id}:${i}`, tipo: 'ce',
            regId: ce.id, cavaloId: ce.eguaId, embIdx: i, qtd,
            data: ce.data,
            garanhao: ia.dados?.garanhao || '',
            iaData: ia.data,
            vetInseminador: ia.vetId,
          });
        }
      }
    }
  }
  for (const ia of iasPrenhez) {
    const d = ia.dados || {};
    const dg15Separado = dgsSeparadosDaIa(registrosRepro, ia).some(dg => {
      if (dg.dados.resultado !== 'positivo') return false;
      const dias = Math.round((new Date(dg.data + 'T12:00:00') - new Date(ia.data + 'T12:00:00')) / 86400000);
      return dias >= 15;
    });
    if (['dg15', 'dg45', 'dg60'].some(k => d[k] === 'positivo') || dg15Separado) {
      embrioesDg15Linhas.push({
        key: `${ia.id}:0`, tipo: 'prenhez',
        regId: ia.id, cavaloId: ia.eguaId, embIdx: 0, qtd: 1,
        data: ia.data,
        garanhao: d.garanhao || '',
        iaData: ia.data,
        vetInseminador: ia.vetId,
      });
    }
  }
  const totalEmbrioesDg15Ce = embrioesDg15Linhas.filter(l => l.tipo === 'ce').length;
  const totalEmbrioesDg15Prenhez = embrioesDg15Linhas.filter(l => l.tipo === 'prenhez').length;

  // ── Prenhezes confirmadas (DG45+) — ancoradas ao mês da IA ───
  // Pra cada IA do mês:
  //  - destino=prenhez: conta se dg45=positivo na própria IA
  //  - destino=transferencia: itera CE+ vinculadas → verifica DG45+ em
  //    cada embrião (via dg45 raiz ou dgsEmbrioes[]) E tbm inovulações
  //    que linkam a essa CE (via ceOrigemId)
  const prenhezesLinhas = [];
  for (const ia of iasPrenhez) {
    const d = ia.dados || {};
    if (d.dg45 !== 'positivo') continue;
    prenhezesLinhas.push({
      key: `${ia.id}:0`, tipo: 'prenhez', regId: ia.id, embIdx: 0, qtd: 1,
      cavaloId: ia.eguaId, data: ia.data,
      garanhao: d.garanhao || '', iaData: ia.data,
      destinoObj: null, receptora: null,
      dg15: d.dg15 || null, dg45: d.dg45 || null, dg60: d.dg60 || null,
      vetInseminador: ia.vetId,
    });
  }
  for (const ia of iasParaTe) {
    const ces = encontraCesDaIa(ia);
    for (const ce of ces) {
      const d = ce.dados || {};
      const qtd = Math.max(1, Number(d.qtdEmbrioes) || 1);
      const destinosArr = Array.isArray(d.destinos) ? d.destinos :
        (Array.isArray(d.receptoras) ? d.receptoras.map(nm => ({ tipo: 'egua', eguaNome: nm || '' })) :
        (d.receptora ? [{ tipo: 'egua', eguaNome: d.receptora }] : []));
      const dgsArr = Array.isArray(d.dgsEmbrioes) ? d.dgsEmbrioes : [];
      // DG45+ marcados diretamente na CE
      for (let i = 0; i < qtd; i++) {
        const emb = (qtd === 1 && dgsArr.length === 0)
          ? { dg15: d.dg15 || null, dg45: d.dg45 || null, dg60: d.dg60 || null, receptora: d.receptora || null }
          : (dgsArr[i] || {});
        if (emb.dg45 !== 'positivo') continue;
        prenhezesLinhas.push({
          key: `${ce.id}:${i}`, tipo: 'ce',
          regId: ce.id, cavaloId: ce.eguaId, embIdx: i, qtd,
          data: ce.data,
          garanhao: ia.dados?.garanhao || d.garanhao || '',
          iaData: ia.data,
          destinoObj: destinosArr[i] || null,
          receptora: emb.receptora || null,
          dg15: emb.dg15 || null, dg45: emb.dg45 || null, dg60: emb.dg60 || null,
          vetInseminador: ia.vetId,
        });
      }
      // Inovulações vinculadas a essa CE (via ceOrigemId) com DG45+
      const inovs = (registrosRepro || []).filter(r =>
        r.tipo === 'inovulacao_embriao' && r.dados?.ceOrigemId === ce.id);
      for (const inov of inovs) {
        if (inov.dados?.dg45 !== 'positivo') continue;
        prenhezesLinhas.push({
          key: `${inov.id}:0`, tipo: 'inovulacao',
          regId: inov.id, cavaloId: inov.eguaId, embIdx: 0, qtd: 1,
          data: inov.data,
          garanhao: ia.dados?.garanhao || inov.dados?.garanhao || '',
          iaData: ia.data,
          destinoObj: null, receptora: null,
          dg15: inov.dados?.dg15 || null, dg45: inov.dados?.dg45 || null, dg60: inov.dados?.dg60 || null,
          vetInseminador: ia.vetId,
        });
      }
    }
  }
  const totalPrenhezes = prenhezesLinhas.length;

  const cards = [
    { label: 'CF', key: 'cf', valor: totalCF, cor: '#0e7490', bg: '#cffafe', clicavel: true, hint: 'Controles foliculares' },
    { label: 'IA', key: 'ia', valor: totalIA, cor: '#7c2d8c', bg: '#f5e8ff', clicavel: true, hint: 'Inseminações' },
    { label: 'CE', key: 'coletas', valor: totalColetas, cor: '#c2410c', bg: '#ffedd5', clicavel: true, hint: 'Coletas de embrião' },
    { label: 'Embr+', key: 'embrioes_pos', valor: totalEmbrioesPos, cor: '#be185d', bg: '#fce7f3', clicavel: true, hint: 'Embriões positivados' },
    { label: 'Prenh.', key: 'prenhezes', valor: totalPrenhezes, cor: '#15803d', bg: '#dcfce7', clicavel: true, hint: 'Prenhezes DG45+' },
  ];

  return (
    <div>
      {!todosMeses && <NavMes mesRef={mesRef} setMesRef={setMesRef} />}
      <div style={{ padding: '8px 20px 4px', display: 'flex', alignItems: 'center', gap: 8 }}>
        <label style={{
          display: 'inline-flex', alignItems: 'center', gap: 6, cursor: 'pointer',
          fontSize: 12, color: todosMeses ? CORES_TAB_ATIVA : 'var(--ink-3)', fontWeight: 600,
        }}>
          <input type="checkbox" checked={todosMeses} onChange={e => setTodosMeses(e.target.checked)}
            style={{ width: 14, height: 14, cursor: 'pointer' }} />
          Ver todos os meses
        </label>
        <div style={{ marginLeft: 'auto', fontSize: 10, color: 'var(--ink-3)' }}>
          {todosMeses ? `${regs.length} registro(s) no total` : `${regs.length} registro(s) no mês`}
        </div>
      </div>
      <div style={{ padding: '4px 20px 8px' }}>
        <FiltroVet vets={vetsExternos} valor={filtroVetId} onChange={setFiltroVetId} />
      </div>

      {semDadosMes && (
        <div style={{
          margin: '8px 20px',
          background: 'var(--card)', border: '1px dashed var(--line)', borderRadius: 12,
          padding: '20px 16px', textAlign: 'center', color: 'var(--ink-3)',
        }}>
          <div style={{ fontSize: 13, marginBottom: 4 }}>Nenhum registro neste mês.</div>
          {totalRegistrosGlobal > 0 && (
            <div style={{ fontSize: 11 }}>
              Existem <strong>{totalRegistrosGlobal}</strong> registro(s) em outros meses. Navegue com ‹ › ou marque <strong>"Ver todos os meses"</strong>.
            </div>
          )}
        </div>
      )}

      <div style={{ padding: '4px 20px 12px', display: 'grid', gridTemplateColumns: `repeat(${cards.length}, 1fr)`, gap: 6 }}>
        {cards.map(c => (
          <button
            key={c.label}
            onClick={c.clicavel ? () => setDetalheAberto(c.key) : undefined}
            disabled={!c.clicavel}
            title={c.hint || c.label}
            style={{
              background: c.bg, border: `1px solid ${c.cor}30`, borderRadius: 12,
              padding: '12px 3px', textAlign: 'center', minWidth: 0,
              cursor: c.clicavel ? 'pointer' : 'default', fontFamily: 'inherit',
            }}>
            <div style={{ fontFamily: 'var(--serif)', fontSize: 26, color: c.cor, lineHeight: 1 }}>{c.valor}</div>
            <div style={{ fontSize: 10, color: c.cor, fontWeight: 700, letterSpacing: '0.06em', marginTop: 4 }}>{c.label}</div>
            {c.hint && <div style={{ fontSize: 9, color: c.cor, opacity: 0.7, marginTop: 2 }}>{c.hint}</div>}
          </button>
        ))}
      </div>

      {/* Análises comparativas — 3 gráficos de barras pareadas que
          medem taxas-chave do funil reprodutivo. */}
      <div style={{ padding: '0 20px 20px' }}>
        <div style={{ fontSize: 11, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8, fontWeight: 700 }}>
          Análises
        </div>
        <GraficoComparativo
          titulo="IA × Embr+"
          hint={`Só entram IAs que já viraram CE ou que já chegaram no DG12 (prenhez na própria égua): ${totalIaResolvidas} de ${totalIA}`}
          valorA={totalIaResolvidas} labelA="IA" corA="#7c2d8c"
          valorB={totalEmbrioesPos} labelB="Embr+" corB="#be185d"
        />
        <GraficoComparativo
          titulo="Embr+ coleta × DG15+"
          hint="Embriões de coletas positivas que viraram DG15+ na receptora"
          valorA={totalEmbrioesPosCe} labelA="Embr+" corA="#be185d"
          valorB={totalEmbrioesDg15Ce} labelB="DG15+" corB="#f59e0b"
        />
        <GraficoComparativo
          titulo="Embr+ própria matriz × DG15+"
          hint="Inseminações pra prenhez na própria matriz com Embr+ que viraram DG15+"
          valorA={totalEmbrioesPosPrenhez} labelA="Embr+" corA="#be185d"
          valorB={totalEmbrioesDg15Prenhez} labelB="DG15+" corB="#f59e0b"
        />
        <GraficoComparativo
          titulo="Embr+ × Prenh."
          hint="Taxa de prenhez confirmada (DG45+) entre os embriões positivados"
          valorA={totalEmbrioesPos} labelA="Embr+" corA="#be185d"
          valorB={totalPrenhezes} labelB="Prenh." corB="#15803d"
        />
        <GraficoComparativo
          titulo="IA × Prenh."
          hint="Taxa geral de sucesso: prenhez confirmada (DG45+) por inseminação"
          valorA={totalIA} labelA="IA" corA="#7c2d8c"
          valorB={totalPrenhezes} labelB="Prenh." corB="#15803d"
        />
      </div>

      {detalheAberto && (
        <DetalhePainelLista
          tipo={detalheAberto}
          iasDoMes={iasDoMes}
          cesAtribuidas={cesAtribuidas}
          cfsDoMes={cfsDoMes}
          embrioesPosLinhas={embrioesPosLinhas}
          coletasLinhas={coletasLinhas}
          prenhezesLinhas={prenhezesLinhas}
          svsDoMes={svsDoMes}
          eguasRepro={eguasRepro}
          vetsExternos={vetsExternos}
          servicos={servicos}
          centraisRepro={centraisRepro}
          iaDeOrigem={iaDeOrigem}
          filtroVetAtivo={!!filtroVetId}
          onClose={() => setDetalheAberto(null)}
        />
      )}
    </div>
  );
}

// Lista detalhada que abre ao clicar em um card do dashboard.
// tipo: 'ia' | 'ce' | 'dg'
function DetalhePainelLista({
  tipo, iasDoMes = [], cesAtribuidas = [], cfsDoMes = [],
  embrioesPosLinhas = [], prenhezesLinhas = [], coletasLinhas = [],
  svsDoMes = [],
  eguasRepro = [], vetsExternos = [], servicos = [], centraisRepro = [],
  iaDeOrigem = null, filtroVetAtivo = false, onClose,
}) {
  const nomeEgua = (id) => eguasRepro.find(e => e.id === id)?.nome || '—';
  const nomeServico = (id) => servicos.find(s => s.id === id)?.nome || '—';
  const corDoVet = (id) => vetsExternos.find(v => v.id === id)?.cor || 'var(--line)';
  const nomeDoVet = (id) => vetsExternos.find(v => v.id === id)?.nome || null;
  const momentoLabel = (m) => m === 'pre_ovulacao' ? 'Pré' : m === 'pos_ovulacao' ? 'Pós' : '—';
  const nomeCentral = (id) => centraisRepro.find(c => c.id === id)?.nome || '—';
  const titulo = tipo === 'ia' ? 'Inseminações'
    : tipo === 'cf' ? 'Controles foliculares'
    : tipo === 'coletas' ? 'Coletas de embrião'
    : tipo === 'embrioes_pos' ? 'Embriões positivados'
    : tipo === 'prenhezes' ? 'Prenhezes confirmadas (DG45+)'
    : tipo === 'sv' ? 'Serviços avulsos'
    : '—';

  // Helpers de UI reutilizados por cada tipo
  const subsIa = (dados) => [
    dados?.qtdPalhetas ? `${dados.qtdPalhetas} palheta(s)` : null,
    dados?.ovulacoes ? `${dados.ovulacoes} ovulação(ões)` : null,
    `Momento: ${momentoLabel(dados?.momento)}`,
    dados?.destino === 'transferencia' ? '→ CE' : dados?.destino === 'prenhez' ? '→ Prenhez' : null,
  ].filter(Boolean);

  let linhas = [];
  if (tipo === 'ia') {
    linhas = [...iasDoMes]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(r => ({
        key: r.id, vetId: r.vetId,
        titulo: `${r.dados?.garanhao || '—'} × ${nomeEgua(r.eguaId)}`,
        subs: [fmtDataBr(r.data), ...subsIa(r.dados)],
      }));
  } else if (tipo === 'cf') {
    linhas = [...cfsDoMes]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(r => {
        const d = r.dados || {};
        const subs = [
          fmtDataBr(r.data),
          d.ovarEsquerdo || d.ovarioDireito ? `OE ${d.ovarEsquerdo || '—'} · OD ${d.ovarioDireito || '—'}` : null,
          d.edemaUterino ? `Edema ${d.edemaUterino}` : null,
          d.tonusUterino ? `TU ${d.tonusUterino}` : null,
          d.ovulou ? '✓ Ovulou' : null,
          d.dataInducaoOvulacao ? `Indução ${fmtDataBr(d.dataInducaoOvulacao)}${d.horaInducaoOvulacao ? ' ' + d.horaInducaoOvulacao : ''}` : null,
        ].filter(Boolean);
        return { key: r.id, vetId: r.vetId, titulo: nomeEgua(r.eguaId), subs };
      });
  } else if (tipo === 'embrioes_pos') {
    linhas = [...embrioesPosLinhas]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(l => ({
        key: l.key, vetId: l.vetInseminador,
        titulo: `${l.garanhao || '—'} × ${nomeEgua(l.cavaloId)}${l.qtd > 1 ? ` · embr. ${l.embIdx + 1}/${l.qtd}` : ''}`,
        chip: l.tipo === 'prenhez'
          ? { label: 'Prenhez na matriz · DG12+', bg: '#fce7f3', ink: '#9d174d' }
          : { label: '✓ Coleta positiva', bg: '#dcfce7', ink: '#15803d' },
        subs: [
          l.iaData ? `IA: ${fmtDataBr(l.iaData)}` : null,
          l.tipo === 'ce' ? `Coleta: ${fmtDataBr(l.data)}` : `Confirmado: ${fmtDataBr(l.data)}`,
        ].filter(Boolean),
      }));
  } else if (tipo === 'coletas') {
    linhas = [...coletasLinhas]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(l => ({
        key: l.key, vetId: l.vetInseminador,
        titulo: `${l.garanhao || '—'} × ${nomeEgua(l.cavaloId)}`,
        chip: l.resultado === 'positivo'
          ? { label: `✓ Positiva${l.qtd > 1 ? ` · ${l.qtd} embr.` : ''}`, bg: '#dcfce7', ink: '#15803d' }
          : l.resultado === 'negativo'
            ? { label: '✗ Negativa', bg: '#fee2e2', ink: '#dc2626' }
            : { label: 'Sem resultado', bg: 'var(--soft)', ink: 'var(--ink-3)' },
        subs: [
          l.iaData ? `IA: ${fmtDataBr(l.iaData)}` : null,
          `Coleta: ${fmtDataBr(l.data)}`,
        ].filter(Boolean),
      }));
  } else if (tipo === 'prenhezes') {
    linhas = [...prenhezesLinhas]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(l => {
        const d = l.destinoObj;
        const destinoLabel = l.tipo === 'prenhez'
          ? `Prenhez na matriz: ${nomeEgua(l.cavaloId)}`
          : l.tipo === 'inovulacao'
            ? `Receptora: ${nomeEgua(l.cavaloId)}`
            : (d?.tipo === 'central'
              ? `Central: ${nomeCentral(d.centralId)}${l.receptora ? ` · Rec.: ${l.receptora}` : ''}`
              : d?.tipo === 'egua'
                ? `Égua: ${d.eguaNome || '—'}`
                : '—');
        return {
          key: l.key, vetId: l.vetInseminador,
          titulo: `${l.garanhao || '—'} × ${nomeEgua(l.cavaloId)}${l.qtd > 1 ? ` · embr. ${l.embIdx + 1}/${l.qtd}` : ''}`,
          chip: { label: '✓ DG45+', bg: '#dcfce7', ink: '#15803d' },
          subs: [
            l.iaData ? `IA: ${fmtDataBr(l.iaData)}` : null,
            destinoLabel,
          ].filter(Boolean),
        };
      });
  } else if (tipo === 'sv') {
    linhas = [...svsDoMes]
      .sort((a, b) => (b.data || '').localeCompare(a.data || ''))
      .map(r => ({
        key: r.id, vetId: r.vetId,
        titulo: nomeServico(r.dados?.servicoId),
        subs: [
          fmtDataBr(r.data),
          `Égua: ${nomeEgua(r.eguaId)}`,
        ],
      }));
  }

  return (
    <Modal onClose={onClose}>
      <div style={{ fontFamily: 'var(--serif)', fontSize: 20, marginBottom: 10 }}>
        {titulo} <span style={{ fontSize: 13, color: 'var(--ink-3)' }}>· {linhas.length}</span>
      </div>
      {linhas.length === 0 && (
        <div style={{ fontSize: 13, color: 'var(--ink-3)', padding: '24px 0', textAlign: 'center' }}>
          Nenhum registro encontrado nesse filtro.
        </div>
      )}
      <div style={{ maxHeight: '60vh', overflowY: 'auto' }}>
        {linhas.map(l => {
          // Borda esquerda com cor do vet, mesmo padrão do kanban/caderno.
          // Quando filtro de vet está ativo, a borda ainda aparece (identifica
          // o inseminador no caso de DG/CE) mas é informação redundante.
          const nomeVet = nomeDoVet(l.vetId);
          return (
            <div key={l.key} style={{
              padding: '10px 10px', borderBottom: '1px solid var(--line)',
              borderLeft: `3px solid ${corDoVet(l.vetId)}`,
              background: 'var(--card)',
              marginBottom: 4, borderRadius: 4,
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 2 }}>
                <div style={{ flex: 1, fontFamily: 'var(--serif)', fontSize: 14, color: 'var(--ink)' }}>{l.titulo}</div>
                {l.chip && (
                  <span style={{
                    fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 4,
                    background: l.chip.bg, color: l.chip.ink,
                  }}>{l.chip.label}</span>
                )}
                {!filtroVetAtivo && nomeVet && (
                  <span style={{
                    fontSize: 10, color: '#fff', background: corDoVet(l.vetId),
                    padding: '2px 6px', borderRadius: 4, fontWeight: 700,
                  }}>{nomeVet.split(' ')[0]}</span>
                )}
              </div>
              <div style={{ fontSize: 11, color: 'var(--ink-3)' }}>{l.subs.join(' · ')}</div>
              {l.dgs && (
                <div style={{ display: 'flex', gap: 10, marginTop: 6 }}>
                  {['dg15', 'dg45', 'dg60'].map(k => (
                    <span key={k} style={{
                      fontSize: 10, fontWeight: 700, padding: '2px 6px', borderRadius: 4,
                      background: l.dgs[k].bg, color: l.dgs[k].ink,
                    }}>{k.toUpperCase()}: {l.dgs[k].label}</span>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
      <button onClick={onClose} style={{
        marginTop: 10, width: '100%', padding: '11px', borderRadius: 10,
        border: '1px solid var(--line)', background: 'var(--card)',
        color: 'var(--ink-2)', fontSize: 13, fontWeight: 600, cursor: 'pointer', fontFamily: 'var(--sans)',
      }}>Fechar</button>
    </Modal>
  );
}

const FiltroVet = ({ vets, valor, onChange }) => (
  <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
    <button onClick={() => onChange('')} style={filtroBtn(!valor)}>Todos</button>
    {vets.map(v => (
      <button key={v.id} onClick={() => onChange(v.id === valor ? '' : v.id)} style={{
        ...filtroBtn(valor === v.id),
        borderColor: valor === v.id ? v.cor : 'var(--line)',
        color: valor === v.id ? v.cor : 'var(--ink-3)',
      }}>
        <span style={{ display: 'inline-block', width: 8, height: 8, borderRadius: 8, background: v.cor, marginRight: 4 }} />
        {v.nome.split(' ')[0]}
      </button>
    ))}
  </div>
);
const filtroBtn = (ativo) => ({
  padding: '6px 10px', borderRadius: 20, border: `1px solid ${ativo ? 'var(--ink)' : 'var(--line)'}`,
  background: ativo ? 'var(--card)' : 'transparent', color: ativo ? 'var(--ink)' : 'var(--ink-3)',
  fontSize: 11, fontWeight: 600, cursor: 'pointer', fontFamily: 'var(--sans)',
});

// Gráfico de duas barras pareadas pra comparar métricas A × B.
// A barra maior tem 100% da largura; a menor é proporcional. Mostra
// os valores absolutos + a taxa B/A em %. Útil pra visualizar funis
// (IA → Embr+ → Prenh.).
const GraficoComparativo = ({ titulo, hint, valorA, labelA, corA, valorB, labelB, corB }) => {
  const max = Math.max(valorA, valorB, 1);
  const pctA = (valorA / max) * 100;
  const pctB = (valorB / max) * 100;
  const taxa = valorA > 0 ? Math.round((valorB / valorA) * 100) : 0;
  return (
    <div style={{
      background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 12, padding: 12, marginBottom: 10,
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: 2 }}>
        <span style={{ fontSize: 13, color: 'var(--ink)', fontWeight: 600 }}>{titulo}</span>
        <span style={{ fontSize: 11, color: 'var(--ink-3)' }}>
          taxa <strong style={{ color: corB }}>{taxa}%</strong>
        </span>
      </div>
      {hint && (
        <div style={{ fontSize: 10, color: 'var(--ink-3)', marginBottom: 8 }}>{hint}</div>
      )}
      {/* Barra A */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
        <span style={{ fontSize: 10, fontWeight: 700, color: corA, width: 42, textAlign: 'right', letterSpacing: '0.03em' }}>{labelA}</span>
        <div style={{ flex: 1, height: 14, background: 'var(--soft)', borderRadius: 4, overflow: 'hidden', position: 'relative' }}>
          <div style={{ width: `${pctA}%`, height: '100%', background: corA, transition: 'width 0.3s' }} />
        </div>
        <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--ink)', minWidth: 24, textAlign: 'right' }}>{valorA}</span>
      </div>
      {/* Barra B */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ fontSize: 10, fontWeight: 700, color: corB, width: 42, textAlign: 'right', letterSpacing: '0.03em' }}>{labelB}</span>
        <div style={{ flex: 1, height: 14, background: 'var(--soft)', borderRadius: 4, overflow: 'hidden', position: 'relative' }}>
          <div style={{ width: `${pctB}%`, height: '100%', background: corB, transition: 'width 0.3s' }} />
        </div>
        <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--ink)', minWidth: 24, textAlign: 'right' }}>{valorB}</span>
      </div>
    </div>
  );
};

