// ── Resultados por garanhão / por égua ──────────────────────
// Ranking de IA × Embr+ com as mesmas regras do Dashboard: a taxa só
// usa IAs que já tiveram tempo de dar resultado (iaResolvida); as
// outras aparecem como "aguardando". IA sem destino não entra.

// Sufixo de criatório/stud-book no fim do nome do garanhão: a equipe
// lança às vezes "Grandorado", às vezes "Grandorado TN" — é o mesmo.
const SUFIXOS_GARANHAO = ['tn', 'z', 'br', 'bh', 'old', 'vdl', 'kwpn', 'sf', 'holst'];
const chaveGaranhao = (nome) => {
  const partes = norm(nome).replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean);
  if (partes.length > 1 && SUFIXOS_GARANHAO.includes(partes[partes.length - 1])) partes.pop();
  return partes.join(' ');
};

function ReproResultados({ por, registrosRepro, eguasRepro = [] }) {
  const hoje = new Date();
  const hojeIso = hoje.toLocaleDateString('sv-SE');
  // Mesmo mês inicial do Dashboard, mas abre em "todos os meses": um
  // mês só tem poucas IAs por garanhão/égua pra comparar.
  const mesInicial = useMemo(() => {
    const datas = (registrosRepro || []).map(r => r.data).filter(Boolean).sort();
    if (datas.length === 0) return { mes: hoje.getMonth() + 1, ano: hoje.getFullYear() };
    const [y, m] = datas[datas.length - 1].split('-');
    return { mes: Number(m), ano: Number(y) };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const [mesRef, setMesRef] = useState(mesInicial);
  const [todosMeses, setTodosMeses] = useState(true);
  const emMes = (iso) => {
    if (!iso) return false;
    const [y, m] = iso.split('-');
    return Number(y) === mesRef.ano && Number(m) === mesRef.mes;
  };

  const grupos = new Map();
  for (const ia of (registrosRepro || [])) {
    if (ia.tipo !== 'inseminacao_artificial') continue;
    if (!todosMeses && !emMes(ia.data)) continue;
    const destino = ia.dados?.destino;
    if (destino !== 'transferencia' && destino !== 'prenhez') continue;
    const nome = por === 'garanhao'
      ? (ia.dados?.garanhao || '').trim()
      : (eguasRepro.find(e => e.id === ia.eguaId)?.nome || '');
    const chave = por === 'garanhao' ? chaveGaranhao(nome) : (ia.eguaId || '');
    if (!grupos.has(chave)) grupos.set(chave, { chave, grafias: new Map(), ia: 0, embr: 0, aguardando: 0 });
    const g = grupos.get(chave);
    if (nome) g.grafias.set(nome, (g.grafias.get(nome) || 0) + 1);
    if (iaResolvida(registrosRepro, ia, hojeIso)) {
      g.ia += 1;
      g.embr += embrioesPosDaIa(registrosRepro, ia);
    } else {
      g.aguardando += 1;
    }
  }

  // Nome mostrado: a grafia mais completa (com o sufixo), depois a mais usada.
  const palavras = (s) => s.split(/\s+/).length;
  const linhas = [...grupos.values()]
    .map(g => ({
      ...g,
      nome: [...g.grafias.entries()]
        .sort((a, b) => palavras(b[0]) - palavras(a[0]) || b[1] - a[1] || a[0].localeCompare(b[0], 'pt'))[0]?.[0] || '',
      taxa: g.ia > 0 ? g.embr / g.ia : null,
    }))
    // Melhor taxa primeiro; empate → mais IAs. Sem resultado ainda e sem
    // garanhão informado vão pro fim.
    .sort((a, b) => {
      if (!a.chave !== !b.chave) return a.chave ? -1 : 1;
      if ((a.taxa === null) !== (b.taxa === null)) return a.taxa === null ? 1 : -1;
      return (b.taxa || 0) - (a.taxa || 0) || b.ia - a.ia || a.nome.localeCompare(b.nome, 'pt');
    });
  let posicao = 0;
  for (const l of linhas) l.posicao = (l.taxa !== null && l.chave) ? ++posicao : null;

  const nomeVazio = por === 'garanhao' ? 'Garanhão não informado' : 'Égua sem cadastro';

  return (
    <div>
      {!todosMeses && <NavMes mesRef={mesRef} setMesRef={setMesRef} />}
      <div style={{ padding: '8px 20px 4px' }}>
        <label style={{
          display: 'inline-flex', alignItems: 'center', gap: 6, cursor: 'pointer',
          fontSize: 12, color: todosMeses ? CORES_TAB_ATIVA : 'var(--ink-3)', fontWeight: 600,
        }}>
          <input type="checkbox" checked={todosMeses} onChange={e => setTodosMeses(e.target.checked)}
            style={{ width: 14, height: 14, cursor: 'pointer' }} />
          Ver todos os meses
        </label>
      </div>
      <div style={{ padding: '4px 20px 8px', fontSize: 10, color: 'var(--ink-3)' }}>
        Embr+ por IA, do melhor para o pior resultado. Só entram IAs que já viraram CE ou que já chegaram no DG12 (prenhez na própria égua).
      </div>

      <div style={{ padding: '0 20px 20px' }}>
        {linhas.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '30px 20px', color: 'var(--ink-3)', fontSize: 13 }}>
            {todosMeses ? 'Nenhuma inseminação registrada.' : 'Nenhuma inseminação neste mês.'}
          </div>
        ) : (
          <div style={{ background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 12, overflow: 'hidden' }}>
            {linhas.map((l, i) => (
              <div key={l.chave || '_'} style={{
                display: 'flex', alignItems: 'center', gap: 10, padding: '10px 12px',
                borderTop: i > 0 ? '1px solid var(--line)' : 'none',
              }}>
                <div style={{ width: 18, fontSize: 11, fontWeight: 700, color: 'var(--ink-3)', textAlign: 'right', flexShrink: 0 }}>
                  {l.posicao || ''}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 14, color: 'var(--ink)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {l.nome || nomeVazio}
                  </div>
                  <div style={{ fontSize: 11, color: 'var(--ink-3)' }}>
                    {l.ia} IA · {l.embr} Embr+{l.aguardando > 0 ? ` · ${l.aguardando} aguardando` : ''}
                  </div>
                </div>
                <div style={{ fontSize: 15, fontWeight: 700, color: l.taxa === null ? 'var(--ink-3)' : '#be185d', flexShrink: 0 }}>
                  {l.taxa === null ? '—' : `${Math.round(l.taxa * 100)}%`}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
// ── Calendário mensal (grid 7×N) ─────────────────────────────
function ReproCalendario({ registrosRepro, eguasRepro, locaisRepro, vetsExternos, onSelectEvento, vetBundle = null, apenasReproducao = false }) {
  const hoje = new Date();
  const [mesRef, setMesRef] = useState({ mes: hoje.getMonth() + 1, ano: hoje.getFullYear() });
  const [diaAberto, setDiaAberto] = useState(null); // iso YYYY-MM-DD

  // Gera 42 células (6 semanas) a partir da 1ª segunda antes/no dia 1
  const primeiroDia = new Date(mesRef.ano, mesRef.mes - 1, 1);
  const primeiroSemana = new Date(primeiroDia);
  primeiroSemana.setDate(primeiroSemana.getDate() - primeiroDia.getDay());
  const celulas = [];
  for (let i = 0; i < 42; i++) {
    const d = new Date(primeiroSemana);
    d.setDate(d.getDate() + i);
    celulas.push(d);
  }

  // Coleta todos os eventos e mapeia por data ISO
  const eventosPorDia = new Map();
  const add = (iso, ev) => {
    if (!iso) return;
    if (!eventosPorDia.has(iso)) eventosPorDia.set(iso, []);
    eventosPorDia.get(iso).push(ev);
  };
  // Registros de reprodução: procedimentos passados aparecem sempre,
  // retorno/coleta/indução só quando ainda não cumpridos.
  for (const r of (registrosRepro || [])) {
    const dados = r.dados || {};
    if (r.data) add(r.data, { r, tipoEv: 'procedimento', dataEv: r.data, fonte: 'repro', ...eventoBase(r) });
    if (r.dataRetorno && !retornoCumprido(r, registrosRepro)) {
      add(r.dataRetorno, { r, tipoEv: 'retorno', dataEv: r.dataRetorno, fonte: 'repro', ...eventoBase(r) });
    }
    if (dados.dataColetaAgendada && !coletaCumprida(r, registrosRepro)) {
      add(dados.dataColetaAgendada, { r, tipoEv: 'coleta', dataEv: dados.dataColetaAgendada, fonte: 'repro', ...eventoBase(r) });
    }
    if (dados.dataInducaoOvulacao && !inducaoCumprida(r, registrosRepro)) {
      add(dados.dataInducaoOvulacao, { r, tipoEv: 'inducao', dataEv: dados.dataInducaoOvulacao, hora: dados.horaInducaoOvulacao || '', fonte: 'repro', ...eventoBase(r) });
    }
  }
  // Eventos vet extras (quando vetBundle é fornecido e apenasReproducao=false):
  // procedimentos, anotações, vacinações, vermifugações, exames, medições, emergências, OPGs
  if (vetBundle && !apenasReproducao) {
    const eguasIds = new Set((eguasRepro || []).map(c => c.id));
    const eventosVet = eventosVetTodos({
      procedimentos: (vetBundle.procedimentos || []).filter(p => eguasIds.has(p.cavaloId)),
      anotacoesClinicas: (vetBundle.anotacoesClinicas || []).filter(a => eguasIds.has(a.cavaloId)),
      vacinacoesAnimais: (vetBundle.vacinacoesAnimais || []).filter(v => eguasIds.has(v.cavaloId)),
      vermifugacoesAnimais: (vetBundle.vermifugacoesAnimais || []).filter(v => eguasIds.has(v.cavaloId)),
      exames: (vetBundle.exames || []).filter(e => eguasIds.has(e.cavaloId)),
      medicoes: (vetBundle.medicoes || []).filter(m => eguasIds.has(m.cavaloId)),
      emergencias: (vetBundle.emergencias || []).filter(em => eguasIds.has(em.cavaloId)),
      opgs: (vetBundle.opgs || []).filter(o => eguasIds.has(o.cavaloId)),
    });
    for (const ev of eventosVet) add(ev.dataEv, ev);
  }

  const isoDe = (d) => d.toISOString().slice(0, 10);
  const hojeIso = isoDe(new Date());
  const mesAtivo = (d) => (d.getMonth() + 1) === mesRef.mes && d.getFullYear() === mesRef.ano;

  const dias = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

  const eventosDia = diaAberto ? (eventosPorDia.get(diaAberto) || []) : [];

  return (
    <div>
      <NavMes mesRef={mesRef} setMesRef={setMesRef} />
      <div style={{ padding: '4px 10px 20px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 2 }}>
          {dias.map((d, i) => (
            <div key={i} style={{ textAlign: 'center', fontSize: 10, color: 'var(--ink-3)', fontWeight: 700, padding: '4px 0' }}>{d}</div>
          ))}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
          {celulas.map((d, i) => {
            const iso = isoDe(d);
            const inMes = mesAtivo(d);
            const isHoje = iso === hojeIso;
            const evs = eventosPorDia.get(iso) || [];
            // até 6 bolinhas (cores dos vets únicos, com repeats por evento)
            const bolinhas = evs.slice(0, 6);
            return (
              <button
                key={i}
                onClick={() => setDiaAberto(iso)}
                style={{
                  aspectRatio: '1 / 1', minHeight: 40,
                  background: isHoje ? '#f5e8ff' : (inMes ? 'var(--card)' : 'transparent'),
                  border: `1px solid ${isHoje ? CORES_TAB_ATIVA : 'var(--line)'}`,
                  borderRadius: 8, padding: 4, cursor: 'pointer',
                  display: 'flex', flexDirection: 'column', alignItems: 'stretch', justifyContent: 'space-between',
                  opacity: inMes ? 1 : 0.35,
                  color: 'var(--ink)',
                }}
              >
                <div style={{
                  fontSize: 11, fontWeight: isHoje ? 700 : 500,
                  color: isHoje ? CORES_TAB_ATIVA : 'var(--ink-2)', textAlign: 'right',
                }}>
                  {d.getDate()}
                </div>
                {bolinhas.length > 0 && (
                  <div style={{ display: 'flex', gap: 2, flexWrap: 'wrap', justifyContent: 'flex-start' }}>
                    {bolinhas.map((ev, j) => {
                      const vet = vetsExternos.find(v => v.id === (ev.vetId || ev.r?.vetId));
                      return (
                        <div key={j} style={{
                          width: 6, height: 6, borderRadius: 6,
                          background: corEventoAmpliado(ev, vet),
                        }} />
                      );
                    })}
                    {evs.length > 6 && (
                      <div style={{ fontSize: 8, color: 'var(--ink-3)', lineHeight: 1 }}>+{evs.length - 6}</div>
                    )}
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {/* Legenda das cores dos vets */}
        {vetsExternos.length > 0 && (
          <div style={{ marginTop: 14, padding: '10px 12px', background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 10 }}>
            <div style={{ fontSize: 10, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 6, fontWeight: 700 }}>Vets</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {vetsExternos.map(v => (
                <div key={v.id} style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: 'var(--ink-2)' }}>
                  <div style={{ width: 8, height: 8, borderRadius: 8, background: v.cor || CORES_TAB_ATIVA }} />
                  {v.nome.split(' ')[0]}
                </div>
              ))}
            </div>
          </div>
        )}
        {vetBundle && !apenasReproducao && (
          <div style={{ marginTop: 10, padding: '10px 12px', background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 10 }}>
            <div style={{ fontSize: 10, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 6, fontWeight: 700 }}>Categorias</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {Object.entries(VET_TIPO_META).map(([k, m]) => (
                <div key={k} style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: 'var(--ink-2)' }}>
                  <div style={{ width: 8, height: 8, borderRadius: 8, background: m.cor }} />
                  {m.label}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {diaAberto && (
        <Modal onClose={() => setDiaAberto(null)}>
          <div style={{ fontFamily: 'var(--serif)', fontSize: 18, marginBottom: 12 }}>
            {fmtDataBr(diaAberto)}
          </div>
          {eventosDia.length === 0 && (
            <div style={{ color: 'var(--ink-3)', fontSize: 13, padding: '10px 0' }}>Sem eventos.</div>
          )}
          {eventosDia.map((ev, i) => {
            const vetId = ev.vetId || ev.r?.vetId;
            const eguaId = ev.eguaId || ev.r?.eguaId;
            const localId = ev.r?.localId;
            const vet = vetsExternos.find(v => v.id === vetId);
            const egua = eguasRepro.find(e => e.id === eguaId);
            const local = locaisRepro.find(l => l.id === localId);
            const rot = rotuloEventoAmpliado(ev);
            const cor = corEventoAmpliado(ev, vet);
            const canOpen = ev.fonte === 'repro' && !!onSelectEvento;
            return (
              <button
                key={i}
                onClick={() => {
                  if (!canOpen) return;
                  setDiaAberto(null);
                  onSelectEvento(ev);
                }}
                style={{
                  width: '100%', textAlign: 'left', cursor: canOpen ? 'pointer' : 'default',
                  background: 'var(--card)', border: '1px solid var(--line)',
                  borderLeft: `3px solid ${cor}`,
                  borderRadius: 10, padding: '10px 12px', marginBottom: 8,
                  color: 'var(--ink)',
                }}
              >
                <div style={{ fontSize: 10, color: cor, textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>
                  {rot}
                </div>
                <div style={{ fontFamily: 'var(--serif)', fontSize: 14, color: 'var(--ink)', marginTop: 2 }}>{egua?.nome || '—'}</div>
                <div style={{ fontSize: 11, color: 'var(--ink-3)', marginTop: 1 }}>
                  {local?.nome || '—'}{vet ? ` · ${vet.nome.split(' ')[0]}` : ''}
                </div>
              </button>
            );
          })}
        </Modal>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Histórico reprodutivo da égua — linha do tempo agrupada por mês.
// Cada evento mostra tipo, cor do vet, campos resumo (garanhão, DG
// resultado, medicamentos etc). Click no card abre o detalhe.
// ─────────────────────────────────────────────────────────────
function HistoricoEgua({ egua, registrosRepro, vetsExternos, locaisRepro, propRepro, onBack, onOpenRegistro }) {
  const [tipoFiltro, setTipoFiltro] = useState('');
  const meus = (registrosRepro || [])
    .filter(r => r.eguaId === egua.id)
    .filter(r => !tipoFiltro || r.tipo === tipoFiltro)
    .sort((a, b) => (b.data || '').localeCompare(a.data || ''));

  const prop = propRepro.find(p => p.id === egua.proprietarioId || (egua.proprietarioIds || []).includes(p.id));

  // Agrupa por mês
  const grupos = new Map();
  const mesesLabels = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  for (const r of meus) {
    const [y, m] = (r.data || '----').split('-');
    const k = `${y}-${m}`;
    if (!grupos.has(k)) grupos.set(k, []);
    grupos.get(k).push(r);
  }
  const gruposOrd = [...grupos.entries()].sort((a, b) => b[0].localeCompare(a[0]));

  // Contagens por tipo pra mostrar filtros com badge
  const contagens = {};
  for (const r of meus) contagens[r.tipo] = (contagens[r.tipo] || 0) + 1;

  const resumoCard = (r) => {
    const d = r.dados || {};
    switch (r.tipo) {
      case 'inseminacao_artificial':
        return [
          d.garanhao && `Garanhão: ${d.garanhao}`,
          d.qtdPalhetas && `${d.qtdPalhetas} palheta(s)`,
          d.momento && d.momento,
          d.destino === 'transferencia' ? '→ Coleta' : (d.destino === 'prenhez' ? '→ Prenhez' : null),
        ].filter(Boolean).join(' · ');
      case 'transferencia_embriao':
        return [
          d.resultado === 'positivo' ? '✓ Positiva' : d.resultado === 'negativo' ? '✗ Negativa' : null,
          d.receptora && `Rec.: ${d.receptora}`,
          d.ringerLactatoL && `${d.ringerLactatoL} L Ringer`,
        ].filter(Boolean).join(' · ');
      case 'controle_folicular':
        return [
          d.ovarioDireito && `OD: ${d.ovarioDireito}`,
          d.ovarEsquerdo && `OE: ${d.ovarEsquerdo}`,
          d.edemaUterino && `edema: ${d.edemaUterino}`,
        ].filter(Boolean).join(' · ');
      case 'diagnostico_gestacao':
        return [
          d.resultado === 'positivo' ? '✓ Gestante' : d.resultado === 'negativo' ? '✗ Vazio' : null,
          d.tamanhoVesicula && `${d.tamanhoVesicula}`,
        ].filter(Boolean).join(' · ');
      case 'tratamento_uterino': {
        const partes = [];
        if (d.tu?.lavagem) partes.push('lavagem');
        if (d.tu?.infusao) partes.push('infusão');
        if (d.tu?.misoprostol) partes.push('misoprostol');
        return partes.join(' + ') || 'tratamento uterino';
      }
      case 'servico_avulso':
        return d.servicoId ? '(serviço)' : '';
      default: return '';
    }
  };

  return (
    <div>
      <TopBar title={egua.nome} subtitle={`Histórico reprodutivo${prop ? ' · ' + prop.nome : ''}`} />
      <div style={{ padding: '4px 20px 0' }}>
        <button onClick={onBack} style={{
          background: 'none', border: 'none', color: 'var(--ink-3)', cursor: 'pointer',
          padding: '6px 0', fontSize: 12, display: 'flex', alignItems: 'center', gap: 4, fontFamily: 'var(--sans)',
        }}>
          <Icon name="arrow-left" size={14} /> Voltar
        </button>
      </div>

      {/* Sumário */}
      <div style={{ padding: '4px 20px 8px' }}>
        <div style={{
          background: 'var(--card)', border: '1px solid var(--line)', borderRadius: 12,
          padding: '10px 14px', display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap',
        }}>
          <div style={{ fontFamily: 'var(--serif)', fontSize: 22 }}>{meus.length}</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>
            registro(s) no total
          </div>
        </div>
      </div>

      {/* Filtro por tipo */}
      <div style={{ padding: '0 20px 8px', display: 'flex', gap: 6, flexWrap: 'wrap' }}>
        <button onClick={() => setTipoFiltro('')} style={filtroBtn(!tipoFiltro)}>Todos</button>
        {Object.entries(contagens).map(([t, n]) => {
          const meta = TIPO_META[t] || {};
          const ativo = tipoFiltro === t;
          return (
            <button key={t} onClick={() => setTipoFiltro(ativo ? '' : t)} style={{
              ...filtroBtn(ativo),
              borderColor: ativo ? meta.cor : 'var(--line)',
              color: ativo ? meta.cor : 'var(--ink-3)',
            }}>{meta.short || t} · {n}</button>
          );
        })}
      </div>

      <div style={{ padding: '4px 20px 20px' }}>
        {meus.length === 0 && (
          <div style={{ textAlign: 'center', padding: '30px 20px', color: 'var(--ink-3)', fontSize: 13 }}>
            Sem registros no caderno.
          </div>
        )}
        {gruposOrd.map(([mesKey, regs]) => {
          const [y, m] = mesKey.split('-');
          const mesLbl = mesKey === '----' ? 'sem data' : `${mesesLabels[Number(m) - 1]} · ${y}`;
          return (
            <div key={mesKey} style={{ marginBottom: 14 }}>
              <div style={{
                fontSize: 11, color: 'var(--ink-3)', textTransform: 'uppercase',
                letterSpacing: '0.08em', fontWeight: 700, marginBottom: 6, padding: '0 4px',
              }}>{mesLbl}</div>
              {regs.map(r => {
                const meta = TIPO_META[r.tipo] || {};
                const vet = vetsExternos.find(v => v.id === r.vetId);
                const local = locaisRepro.find(l => l.id === r.localId);
                return (
                  <button key={r.id} onClick={() => onOpenRegistro && onOpenRegistro(r)} style={{
                    width: '100%', textAlign: 'left', cursor: onOpenRegistro ? 'pointer' : 'default',
                    background: 'var(--card)', border: '1px solid var(--line)',
                    borderLeft: `3px solid ${vet?.cor || meta.cor || CORES_TAB_ATIVA}`,
                    borderRadius: 10, padding: '10px 12px', marginBottom: 6, color: 'var(--ink)',
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 2, flexWrap: 'wrap' }}>
                      <span style={{
                        fontSize: 10, background: meta.bg || 'var(--soft)', color: meta.cor || 'var(--ink)',
                        padding: '2px 6px', borderRadius: 4, fontWeight: 700,
                      }}>{meta.short || r.tipo}</span>
                      <span style={{ fontSize: 11, color: 'var(--ink-3)' }}>{fmtDataBr(r.data)}</span>
                      {vet && (
                        <span style={{ fontSize: 10, color: '#fff', background: vet.cor, padding: '1px 6px', borderRadius: 4, fontWeight: 700 }}>
                          {vet.nome.split(' ')[0]}
                        </span>
                      )}
                      {local && (
                        <span style={{ fontSize: 10, color: 'var(--ink-3)' }}>· {local.nome}</span>
                      )}
                    </div>
                    <div style={{ fontFamily: 'var(--sans)', fontSize: 12, color: 'var(--ink-2)' }}>
                      {resumoCard(r)}
                    </div>
                    {/* DG marcados no detalhe — mostra legado e por embrião */}
                    {(() => {
                      const arr = Array.isArray(r.dados?.dgsEmbrioes) ? r.dados.dgsEmbrioes : null;
                      const badges = [];
                      if (arr && arr.length > 0) {
                        arr.forEach((e, i) => {
                          ['dg15', 'dg45', 'dg60'].forEach(k => {
                            if (e?.[k]) badges.push({ chave: `e${i}${k}`, label: `E${i + 1} ${k.toUpperCase()}`, valor: e[k] });
                          });
                        });
                      } else if (r.dados) {
                        ['dg15', 'dg45', 'dg60'].forEach(k => {
                          if (r.dados[k]) badges.push({ chave: k, label: k.toUpperCase(), valor: r.dados[k] });
                        });
                      }
                      if (badges.length === 0) return null;
                      return (
                        <div style={{ display: 'flex', gap: 4, marginTop: 4, flexWrap: 'wrap' }}>
                          {badges.map(b => (
                            <span key={b.chave} style={{
                              fontSize: 9, padding: '1px 5px', borderRadius: 3, fontWeight: 700,
                              background: b.valor === 'positivo' ? '#dcfce7' : '#fee2e2',
                              color: b.valor === 'positivo' ? '#15803d' : '#991b1b',
                            }}>{b.label} {b.valor === 'positivo' ? '+' : '-'}</span>
                          ))}
                        </div>
                      );
                    })()}
                    {/* Anexos (Diagnóstico) */}
                    {r.dados?.anexos?.length > 0 && (
                      <div style={{ display: 'flex', gap: 4, marginTop: 4, flexWrap: 'wrap' }}>
                        {r.dados.anexos.map(a => (
                          <a key={a.id} href={a.url} target="_blank" rel="noopener noreferrer"
                            onClick={e => e.stopPropagation()}
                            style={{
                              fontSize: 10, padding: '2px 8px', borderRadius: 4, fontWeight: 600,
                              background: '#e0f2fe', color: '#0284c7', textDecoration: 'none',
                              display: 'inline-flex', alignItems: 'center', gap: 4,
                            }}>
                            📎 {a.nome.length > 20 ? a.nome.slice(0, 18) + '…' : a.nome}
                          </a>
                        ))}
                      </div>
                    )}
                  </button>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

