// ─────────────────────────────────────────────────────────────
// Cálculo de fatura mensal do Epona Repro Team
//
// Componentes:
//   1. Visitas (km) — cada (vet, data, local) do mês gera 1 visita.
//      O valor cadastrado em vet_km_por_local é rateado entre o número
//      de PROPRIETÁRIOS distintos atendidos naquele dia+local. Sem valor
//      cadastrado pro vet naquele local, a visita entra com R$ 0 e
//      semKm=true (antes sumia da fatura sem aviso). Ajustes manuais da
//      fatura (faturas_repro_ajustes) excluem ou acrescentam visitas.
//   2. Insumos — vêm dos registros do caderno via `insumosUsados`
//      ({insumoId, qtd}). Cobrados por valorVenda × qtd.
//   3. Procedimentos IA/TE — 1 linha por registro, com o preço do
//      serviço do catálogo repro (por nome: "IA" ou "TE") como
//      fallback → serviço com nome contendo "insemin"/"transferência".
//   4. Serviços avulsos — registros do tipo 'servico_avulso' com
//      valor cobrado no próprio registro.
//   5. Resultado reprodutivo — cobrado no DG30+. Valor vem de
//      proprietario.valorResultadoRepro.
//
// A função retorna estrutura suficiente pra renderizar tela + PDF +
// alimentar a divisão da equipe (com metadata de vet responsável e
// insumos/procs individuais).
// ─────────────────────────────────────────────────────────────

const norm = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

// Retorna os OBJETOS dos serviços "IA" e "TE" cadastrados (workspace
// repro tem prioridade sobre haras). Fonte da verdade pra preço e pra
// lista de descartáveis obrigatórios.
// Busca por serviço (não por "pool"): antes, se existisse 1 serviço repro,
// só o pool repro era consultado (CE ficava R$ 0 quando a coleta estava
// cadastrada como haras), e o padrão /te\b|ce\b/ casava qualquer palavra
// terminada em "te"/"ce" ("Transporte", "Pensão égua gestante", "Frete").
export function servicosPadrao(servicos) {
  const svRepro = servicos.filter(s => (s.workspaceId || 'haras') === 'repro');
  const svHaras = servicos.filter(s => (s.workspaceId || 'haras') !== 'repro');
  const n = (s) => norm(s.nome || '').trim();
  const isIa = (s) => /insemina/.test(n(s));
  const isTeEstrito = (s) => /(coleta|transferencia)\s+(de\s+)?embri|^(ce|te)\b|\((ce|te)\)/.test(n(s));
  const isTeAmplo = (s) => /^coleta\b|^transferencia\b/.test(n(s));
  // Variantes "+" e "−" (ou "-") no nome diferenciam coleta positiva × negativa.
  // Descartáveis obrigatórios diferem (CE+ gasta mais material); valor costuma
  // ser o mesmo. teGenerico mantido como fallback pra fluxo antigo com 1 serviço só.
  const isTePositivo = (s) => isTeEstrito(s) && /[+]/.test(s.nome || '');
  const isTeNegativo = (s) => isTeEstrito(s) && /[-−]/.test(s.nome || '');
  const achar = (pred) => svRepro.find(pred) || svHaras.find(pred) || null;
  const tePositivo = achar(isTePositivo);
  const teNegativo = achar(isTeNegativo);
  // Genérico: 1º TE sem +/− no nome (quando existe só uma opção)
  const teGenerico = achar(s => isTeEstrito(s) && !isTePositivo(s) && !isTeNegativo(s))
    || achar(isTeAmplo);
  return {
    ia: achar(isIa),
    te: tePositivo || teNegativo || teGenerico,
    tePositivo, teNegativo, teGenerico,
  };
}

// Resolve qual serviço TE usar baseado no resultado da coleta.
// - 'positivo' → serviço "+" (mais descartáveis: ringer, filtros, etc.)
// - 'negativo' → serviço "-" (menos descartáveis)
// - vazio/ainda não marcado → genérico ou negativo como default
export function servicoTeParaResultado(servicos, resultado) {
  const p = servicosPadrao(servicos);
  if (resultado === 'positivo') return p.tePositivo || p.teGenerico || p.te;
  if (resultado === 'negativo') return p.teNegativo || p.teGenerico || p.te;
  return p.teGenerico || p.teNegativo || p.te;
}
export function precosPadraoServicos(servicos) {
  const p = servicosPadrao(servicos);
  return {
    ia: Number(p.ia?.valor || 0),
    te: Number(p.te?.valor || 0),
  };
}

function isMes(dataIso, ref) {
  if (!dataIso) return false;
  const [y, m] = dataIso.split('-');
  return Number(y) === ref.ano && Number(m) === ref.mes;
}

// Rastreio da cadeia IA → TE → DG30 pra dividir o resultado
// reprodutivo entre vet e Epona (50/50).
// - Prioridade 1: DG30.dados.iaOrigemId (herdado do TE se preenchido)
// - Prioridade 2: TE mais recente da mesma égua antes do DG30 →
//   te.dados.iaOrigemId
// - Prioridade 3: TE mais recente da mesma égua antes do DG30 (heurística)
//   → última IA da égua antes daquela TE
// Retorna { iaId, vetId } ou null.
export function rastrearIaDoDg(dg, registros) {
  if (!dg) return null;
  // Se DG30 marca dg30 num TE, ele NÃO é um registro dg30 avulso — é o
  // próprio TE com dados.dg30. Nesse caso, o "dg" já é o TE.
  // Se DG30 é um registro tipo=diagnostico_gestacao, temos:
  //   dg.data | dg.eguaId | (opcional) dg.dados.teOrigemId
  const eguaId = dg.eguaId;
  const dataDg = dg.data;
  if (!eguaId) return null;

  // Se já tem iaOrigemId direto
  if (dg.dados?.iaOrigemId) {
    const ia = registros.find(r => r.id === dg.dados.iaOrigemId);
    return ia ? { iaId: ia.id, vetId: ia.vetId } : null;
  }
  // Se tem teOrigemId, busca a TE e usa ia dela
  const teFromId = dg.dados?.teOrigemId
    ? registros.find(r => r.id === dg.dados.teOrigemId)
    : null;
  if (teFromId?.dados?.iaOrigemId) {
    const ia = registros.find(r => r.id === teFromId.dados.iaOrigemId);
    if (ia) return { iaId: ia.id, vetId: ia.vetId };
  }
  // Heurística: TE mais recente da égua antes/igual do DG
  const tes = registros
    .filter(r => r.tipo === 'transferencia_embriao' && r.eguaId === eguaId
      && (r.dados?.resultado === 'positivo') && (r.data || '') <= (dataDg || ''))
    .sort((a, b) => (b.data || '').localeCompare(a.data || ''));
  const te = tes[0];
  if (te?.dados?.iaOrigemId) {
    const ia = registros.find(r => r.id === te.dados.iaOrigemId);
    if (ia) return { iaId: ia.id, vetId: ia.vetId };
  }
  // Última IA da égua com destino=transferencia antes da TE
  const refData = te?.data || dataDg;
  const ias = registros
    .filter(r => r.tipo === 'inseminacao_artificial' && r.eguaId === eguaId
      && (r.dados?.destino === 'transferencia') && (r.data || '') <= (refData || ''))
    .sort((a, b) => (b.data || '').localeCompare(a.data || ''));
  const ia = ias[0];
  if (ia) return { iaId: ia.id, vetId: ia.vetId };

  // Último fallback: IA prenhez própria (fluxo sem TE)
  const iasPrenhez = registros
    .filter(r => r.tipo === 'inseminacao_artificial' && r.eguaId === eguaId
      && (r.dados?.destino === 'prenhez') && (r.data || '') <= (dataDg || ''))
    .sort((a, b) => (b.data || '').localeCompare(a.data || ''));
  if (iasPrenhez[0]) return { iaId: iasPrenhez[0].id, vetId: iasPrenhez[0].vetId };

  return null;
}

// dg30Positivos: retorna lista dos DG30+ do mês (independente de estar
// num registro tipo=diagnostico_gestacao ou embutido no TE via
// dados.dg30 = 'positivo'). Cada item traz { registroOrigem, data,
// eguaId, iaOrigem }.
export function dg30PositivosDoMes(registros, ref) {
  const out = [];
  for (const r of registros) {
    if ((r.workspaceId || 'haras') !== 'repro') continue;
    // 1) Registro dedicado de DG30
    if (r.tipo === 'diagnostico_gestacao' && r.dados?.resultado === 'positivo'
        && r.dados?.tipoDg === 'dg30' && isMes(r.data, ref)) {
      out.push({ registroOrigem: r, data: r.data, eguaId: r.eguaId, ia: rastrearIaDoDg(r, registros) });
      continue;
    }
    // 2) DG30 marcado dentro do detalhe do TE (r.dados.dg30 = 'positivo',
    //    r.dados.dg30_data = 'YYYY-MM-DD'). Nesse caso a data é a do dg30.
    if (r.dados?.dg30 === 'positivo' && r.dados?.dg30_data && isMes(r.dados.dg30_data, ref)) {
      out.push({
        registroOrigem: r, data: r.dados.dg30_data, eguaId: r.eguaId,
        ia: rastrearIaDoDg({ eguaId: r.eguaId, data: r.dados.dg30_data, dados: r.dados }, registros),
      });
    }
  }
  return out;
}

// DG45 positivos do mês — 1 item POR EMBRIÃO confirmado.
// Cobrança do valor de resultado reprodutivo acontece aqui.
// Suporta:
//   - dg45 legacy (dados.dg45 === 'positivo') — 1 embrião só
//   - dgsEmbrioes array (múltiplos embriões na mesma coleta)
export function dg45PositivosDoMes(registros, ref) {
  const out = [];
  for (const r of registros) {
    if ((r.workspaceId || 'haras') !== 'repro') continue;
    // 1) Registro dedicado tipo diagnostico_gestacao com tipoDg='dg45'
    if (r.tipo === 'diagnostico_gestacao' && r.dados?.resultado === 'positivo'
        && r.dados?.tipoDg === 'dg45' && isMes(r.data, ref)) {
      out.push({ registroOrigem: r, data: r.data, eguaId: r.eguaId, embIdx: 0, ia: rastrearIaDoDg(r, registros) });
      continue;
    }
    // Um registro usa OU o formato legado (1 embrião, dados.dg45) OU o
    // formato por embrião (dgsEmbrioes) — nunca os dois. Antes os dois eram
    // somados (DG45 cobrado em dobro), e embriões além de qtdEmbrioes
    // (após reduzir a quantidade) continuavam cobrados.
    const qtdEmb = Number(r.dados?.qtdEmbrioes) || 1;
    const arrEmb = Array.isArray(r.dados?.dgsEmbrioes) ? r.dados.dgsEmbrioes : [];
    const usaPorEmbriao = qtdEmb > 1 && arrEmb.length > 0;
    // 2) DG45 marcado no detalhe (legacy — 1 embrião)
    if (!usaPorEmbriao && r.dados?.dg45 === 'positivo' && r.dados?.dg45_data && isMes(r.dados.dg45_data, ref)) {
      out.push({
        registroOrigem: r, data: r.dados.dg45_data, eguaId: r.eguaId, embIdx: 0,
        ia: rastrearIaDoDg({ eguaId: r.eguaId, data: r.dados.dg45_data, dados: r.dados }, registros),
      });
    }
    // 3) CE com múltiplos embriões: dgsEmbrioes[i].dg45 === 'positivo'
    const arr = usaPorEmbriao ? arrEmb : [];
    for (let i = 0; i < Math.min(arr.length, qtdEmb); i++) {
      const e = arr[i];
      if (e?.dg45 === 'positivo' && e?.dg45_data && isMes(e.dg45_data, ref)) {
        out.push({
          registroOrigem: r, data: e.dg45_data, eguaId: r.eguaId, embIdx: i,
          receptora: (r.dados.receptoras || [])[i] || null,
          ia: rastrearIaDoDg({ eguaId: r.eguaId, data: e.dg45_data, dados: r.dados }, registros),
        });
      }
    }
  }
  return out;
}

// Retorna nova lista de insumos com descartáveis agrupados numa
// única linha "Descartáveis". Usada nas faturas admin/repro.
// Preserva as linhas originais em `.detalhe` pra debug / re-expansão.
export function agruparDescartaveisLinhas(insumosLinhas, insumosCatalogo = []) {
  const isDesc = (l) => {
    const ins = insumosCatalogo.find(i => i.id === l.insumoId);
    return ins && ins.categoria === 'descartavel';
  };
  const descartaveis = insumosLinhas.filter(isDesc);
  const outros = insumosLinhas.filter(l => !isDesc(l));
  if (descartaveis.length === 0) return outros;
  const totalDesc = descartaveis.reduce((s, l) => s + l.valor, 0);
  const linhaAgg = {
    data: descartaveis[0].data,
    registroId: null,
    insumoId: '__descartaveis__',
    nome: 'Descartáveis',
    qtd: descartaveis.reduce((s, l) => s + (Number(l.qtd) || 0), 0),
    unidade: 'itens',
    unitario: 0,
    valor: totalDesc,
    agrupado: true,
    detalhe: descartaveis,
  };
  return [linhaAgg, ...outros];
}

export function calcFaturaRepro(propId, ref, deps, opts = {}) {
  const {
    registros = [], cavalos = [], proprietarios = [],
    servicos = [], insumos = [], vetKmLocais = [], locais = [],
    // Assessoria clínica (opcional — se não vier, seção fica vazia)
    contratosAssessoria = [], visitasClinicas = [],
    // Processos genealógicos (ABCCH) — pra cobrar inspeção realizada
    genealogicos = [],
    // Ajustes manuais de visitas feitos na própria fatura
    ajustesFaturas = [],
  } = deps;
  const { agruparDescartaveis = false } = opts;

  const prop = proprietarios.find(p => p.id === propId);
  const cavalosProp = cavalos.filter(c =>
    ((c.proprietarioIds || []).includes(propId) || c.proprietarioId === propId)
    && (c.workspaceId || 'haras') === 'repro',
  );
  const cavalosIds = new Set(cavalosProp.map(c => c.id));

  const regsRepro = registros.filter(r => (r.workspaceId || 'haras') === 'repro');
  const regsMesProp = regsRepro.filter(r => cavalosIds.has(r.eguaId) && isMes(r.data, ref));

  const precos = precosPadraoServicos(servicos);

  // ── 1) Visitas (rateio de km por proprietários distintos no
  //       mesmo dia+local do mesmo vet)
  const visitasMap = new Map(); // key: `${vetId}|${data}|${localId}` → { vetId, data, localId, propriedades: Set, cavalosDoProp: Set }
  for (const r of regsRepro) {
    if (!r.vetId || !r.localId || !r.data) continue;
    if (!isMes(r.data, ref)) continue;
    const cav = cavalos.find(c => c.id === r.eguaId);
    if (!cav) continue;
    const propsDoCav = (cav.proprietarioIds && cav.proprietarioIds.length > 0)
      ? cav.proprietarioIds
      : (cav.proprietarioId ? [cav.proprietarioId] : []);
    const key = `${r.vetId}|${r.data}|${r.localId}`;
    if (!visitasMap.has(key)) {
      visitasMap.set(key, {
        vetId: r.vetId, data: r.data, localId: r.localId,
        propriedades: new Set(),
        temPropAtual: false,
      });
    }
    const v = visitasMap.get(key);
    propsDoCav.forEach(pid => v.propriedades.add(pid));
    if (propsDoCav.includes(propId)) v.temPropAtual = true;
  }
  const ajustesDaFatura = ajustesFaturas.filter(a =>
    a.proprietarioId === propId && a.ano === ref.ano && a.mes === ref.mes);
  const excluidasPorChave = new Map(ajustesDaFatura
    .filter(a => a.tipo === 'visita_excluida')
    .map(a => [a.dados?.chave, a]));
  const visitasLinhas = [];
  const visitasExcluidas = [];
  for (const v of visitasMap.values()) {
    if (!v.temPropAtual) continue;
    const km = vetKmLocais.find(k => k.vetId === v.vetId && k.localId === v.localId);
    const valorBase = Number(km?.valor) || 0;
    const nProps = v.propriedades.size || 1;
    const rateado = valorBase / nProps;
    const local = locais.find(l => l.id === v.localId);
    const chave = `${v.vetId}|${v.data}|${v.localId}`;
    const linha = {
      data: v.data, vetId: v.vetId, localId: v.localId,
      localNome: local?.nome || '—',
      valorBase, nProps, valor: rateado,
      chave, semKm: !km,
    };
    const exclusao = excluidasPorChave.get(chave);
    if (exclusao) visitasExcluidas.push({ ...linha, ajusteId: exclusao.id });
    else visitasLinhas.push(linha);
  }
  for (const a of ajustesDaFatura) {
    if (a.tipo !== 'visita_adicionada') continue;
    const d = a.dados || {};
    const local = locais.find(l => l.id === d.localId);
    const valor = Number(d.valor) || 0;
    visitasLinhas.push({
      data: d.data, vetId: d.vetId || null, localId: d.localId || null,
      localNome: local?.nome || d.localNome || '—',
      valorBase: valor, nProps: 1, valor,
      manual: true, ajusteId: a.id, eguasIds: d.eguasIds || [],
    });
  }
  visitasLinhas.sort((a, b) => (a.data || '').localeCompare(b.data || ''));
  const visitasTotal = visitasLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 2) Insumos (por registro do proprietário no mês)
  const insumosLinhas = [];
  for (const r of regsMesProp) {
    for (const u of (r.insumosUsados || [])) {
      const ins = insumos.find(i => i.id === u.insumoId);
      if (!ins) continue;
      const qtd = Number(u.qtd) || 0;
      const subtotal = (Number(ins.valorVenda) || 0) * qtd;
      insumosLinhas.push({
        data: r.data, registroId: r.id, insumoId: ins.id, nome: ins.nome,
        qtd, unidade: ins.unidade || 'un', unitario: Number(ins.valorVenda) || 0, valor: subtotal,
        vetId: r.vetId || null,
      });
    }
  }
  const insumosTotal = insumosLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 3) Procedimentos IA/TE (do mês, proprietário atual)
  const procedimentosLinhas = [];
  for (const r of regsMesProp) {
    if (r.tipo === 'inseminacao_artificial') {
      procedimentosLinhas.push({
        data: r.data, registroId: r.id, tipo: 'IA', vetId: r.vetId,
        descricao: `Inseminação Artificial${r.dados?.garanhao ? ' — ' + r.dados.garanhao : ''}`,
        valor: precos.ia,
      });
    } else if (r.tipo === 'transferencia_embriao') {
      procedimentosLinhas.push({
        data: r.data, registroId: r.id, tipo: 'CE', vetId: r.vetId,
        descricao: 'Coleta de Embrião',
        valor: precos.te,
      });
    } else if (r.tipo === 'inovulacao_embriao') {
      // Serviço "Inovulação de Embrião" é cadastrado pela usuária em
      // Serviços. Busca por nome.
      const svInov = servicos.find(s => /inovul/i.test(s.nome || ''));
      procedimentosLinhas.push({
        data: r.data, registroId: r.id, tipo: 'IE', vetId: r.vetId,
        descricao: `Inovulação de Embrião${r.dados?.garanhao ? ' — ' + r.dados.garanhao : ''}`,
        valor: Number(svInov?.valor) || 0,
      });
    }
  }
  const procedimentosTotal = procedimentosLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 4) Serviços avulsos + Tratamento Uterino (do mês, propr. atual)
  const avulsosLinhas = [];
  // Matchers pra pegar preço dos serviços de Tratamento Uterino do catálogo
  const svcTratamento = servicos.find(s => /tratamento.*uter/i.test(norm(s.nome || '')));
  const svcOzonio = servicos.find(s => /ozonio/i.test(norm(s.nome || '')));
  // Mesmo critério do TU_MATCHERS.servPrp (serviço cadastrado como "PRP").
  const svcPrp = servicos.find(s => /\bprp\b/i.test(norm(s.nome || '')));

  for (const r of regsMesProp) {
    if (r.tipo === 'servico_avulso') {
      const sv = servicos.find(s => s.id === r.dados?.servicoId);
      const valor = Number(r.dados?.valorCobrado) || Number(sv?.valor) || 0;
      avulsosLinhas.push({
        data: r.data, registroId: r.id, vetId: r.vetId, servicoId: r.dados?.servicoId || null,
        descricao: sv?.nome || 'Serviço avulso', valor,
        // Transporte (Motoboy, Frete) fica 100% com o vet na divisão
        categoria: sv?.categoria || null,
      });
      continue;
    }
    if (r.tipo === 'tratamento_uterino') {
      // Serviço base
      if (svcTratamento) {
        avulsosLinhas.push({
          data: r.data, registroId: r.id, vetId: r.vetId, servicoId: svcTratamento.id,
          descricao: svcTratamento.nome, valor: Number(svcTratamento.valor) || 0,
        });
      }
      // Serviços adicionais marcados
      if (r.dados?.tu?.lavagem?.ozonio && svcOzonio) {
        avulsosLinhas.push({
          data: r.data, registroId: r.id, vetId: r.vetId, servicoId: svcOzonio.id,
          descricao: svcOzonio.nome, valor: Number(svcOzonio.valor) || 0,
        });
      }
      if (r.dados?.tu?.infusao?.prp && svcPrp) {
        avulsosLinhas.push({
          data: r.data, registroId: r.id, vetId: r.vetId, servicoId: svcPrp.id,
          descricao: svcPrp.nome, valor: Number(svcPrp.valor) || 0,
        });
      }
    }
    if (r.tipo === 'diagnostico_avulso') {
      const svcBio = servicos.find(s => /bi[oó]psia.*endometr/i.test(norm(s.nome || '')));
      const svcCul = servicos.find(s => /cultura.*antibiograma/i.test(norm(s.nome || '')));
      if (r.dados?.dx?.biopsia && svcBio) {
        avulsosLinhas.push({
          data: r.data, registroId: r.id, vetId: r.vetId, servicoId: svcBio.id,
          descricao: svcBio.nome, valor: Number(svcBio.valor) || 0,
        });
      }
      if (r.dados?.dx?.cultura && svcCul) {
        avulsosLinhas.push({
          data: r.data, registroId: r.id, vetId: r.vetId, servicoId: svcCul.id,
          descricao: svcCul.nome, valor: Number(svcCul.valor) || 0,
        });
      }
    }
  }
  const avulsosTotal = avulsosLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 5) Resultado reprodutivo (DG45+ do mês, cavalos do proprietário)
  // Cobra 1× por embrião confirmado no DG45. Coletas com múltiplos
  // embriões geram múltiplas linhas.
  const resultadosLinhas = [];
  const dg45Mes = dg45PositivosDoMes(regsRepro, ref);
  for (const dg of dg45Mes) {
    if (!cavalosIds.has(dg.eguaId)) continue;
    const cav = cavalos.find(c => c.id === dg.eguaId);
    const valor = Number(prop?.valorResultadoRepro) || 0;
    if (valor <= 0) continue;
    const qtdEmb = Math.max(1, Number(dg.registroOrigem?.dados?.qtdEmbrioes) || 1);
    resultadosLinhas.push({
      data: dg.data, eguaId: dg.eguaId, eguaNome: cav?.nome || 'égua',
      iaId: dg.ia?.iaId || null, vetIdInsem: dg.ia?.vetId || null,
      embrioIdx: dg.embIdx,
      totalEmbrioes: qtdEmb,
      receptora: dg.receptora || null,
      valor,
    });
  }
  const resultadosTotal = resultadosLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 5b) Aluguel de Receptora: embrião NOSSO (coletado por nós) foi
  // transferido para receptora de OUTRO proprietário e deu DG45+. Cobra
  // o valorAluguelReceptora do DONO DA RECEPTORA, na fatura do dono da
  // DOADORA. Se mesmo dono, não cobra.
  //
  // Fonte: inovulações do mês onde:
  //   - A receptora (r.eguaId) existe cadastrada em outro proprietário
  //   - DG45 positivo marcado em r.dados.dg45 (data no mês ref)
  //   - A inovulação tem ceOrigemId apontando pra CE+ de uma doadora
  //     deste proprietário (propId)
  const alugueisLinhas = [];
  for (const r of regsRepro) {
    if (r.tipo !== 'inovulacao_embriao') continue;
    const dg45Data = r.dados?.dg45_data;
    if (r.dados?.dg45 !== 'positivo' || !dg45Data) continue;
    if (!isMes(dg45Data, ref)) continue;
    const receptoraEgua = cavalos.find(c => c.id === r.eguaId);
    if (!receptoraEgua) continue;
    const donosReceptora = (receptoraEgua.proprietarioIds && receptoraEgua.proprietarioIds.length > 0)
      ? receptoraEgua.proprietarioIds
      : (receptoraEgua.proprietarioId ? [receptoraEgua.proprietarioId] : []);
    // Receptora precisa ser de OUTRO proprietário
    if (donosReceptora.length === 0) continue;
    if (donosReceptora.includes(propId)) continue;
    // Doadora: via ceOrigemId. Precisa pertencer a este propId.
    const ce = r.dados?.ceOrigemId ? registros.find(x => x.id === r.dados.ceOrigemId) : null;
    if (!ce) continue;
    const doadora = cavalos.find(c => c.id === ce.eguaId);
    if (!doadora) continue;
    const donosDoadora = (doadora.proprietarioIds && doadora.proprietarioIds.length > 0)
      ? doadora.proprietarioIds
      : (doadora.proprietarioId ? [doadora.proprietarioId] : []);
    if (!donosDoadora.includes(propId)) continue;
    // Valor: do dono da receptora
    const donoRec = proprietarios.find(p => p.id === donosReceptora[0]);
    const valor = Number(donoRec?.valorAluguelReceptora) || 0;
    if (valor <= 0) continue;
    alugueisLinhas.push({
      data: dg45Data, inovulacaoId: r.id, ceId: ce.id,
      receptoraNome: receptoraEgua.nome,
      doadoraNome: doadora.nome,
      donoReceptoraNome: donoRec?.nome || '—',
      valor,
    });
  }
  const alugueisTotal = alugueisLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 6) Assessoria clínica (visitas finalizadas do mês dos contratos
  //       deste proprietário). Cada visita vira 1 linha; divisão é feita
  //       por dividirFatura com regra especial (Epona 100% se só internos;
  //       Epona 50% + externos dividem 50%).
  const contratosDoProp = contratosAssessoria.filter(c => c.proprietarioId === propId);
  const idsContratos = new Set(contratosDoProp.map(c => c.id));
  const assessoriasLinhas = [];
  for (const v of visitasClinicas) {
    if (v.status !== 'finalizada') continue;
    if (!idsContratos.has(v.contratoId)) continue;
    if (!isMes(v.data, ref)) continue;
    const c = contratosDoProp.find(x => x.id === v.contratoId);
    const insumosExtras = Array.isArray(v.insumosCobrados) ? v.insumosCobrados : [];
    const totalInsumos = insumosExtras.reduce(
      (s, it) => s + (Number(it.qtd) || 0) * (Number(it.valorUnit) || 0), 0,
    );
    assessoriasLinhas.push({
      data: v.data,
      visitaId: v.id,
      contratoId: v.contratoId,
      descricao: c?.nomeApelido ? `Assessoria · ${c.nomeApelido}` : 'Assessoria mensal',
      // valor = mensal + extras (insumos que a Epona forneceu nesta visita)
      valor: (Number(v.valorCobrado) || 0) + totalInsumos,
      valorBase: Number(v.valorCobrado) || 0,
      insumosExtras,
      totalInsumos,
      vetsParticipantes: v.vetsParticipantes || [],
    });
  }
  assessoriasLinhas.sort((a, b) => (a.data || '').localeCompare(b.data || ''));
  const assessoriasTotal = assessoriasLinhas.reduce((s, l) => s + l.valor, 0);

  // ── 7) Inspeções ABCCH realizadas no mês. Linha pra cada processo
  //       genealógico com inspecaoFeita=true e inspecao_data no mês ref.
  //       Cobra: valor do serviço "Inspeção ABCCH" (busca por nome) +
  //       valor de visita (km) declarado no form de registro.
  const inspecoesLinhas = [];
  const svcInspecao = servicos.find(s => /inspe[çc][ãa]o.*abcch|abcch.*inspe/i.test(s.nome || ''));
  const valorInspecao = Number(svcInspecao?.valor) || 0;
  for (const g of (genealogicos || [])) {
    if (!g.inspecaoFeita || !g.inspecaoData) continue;
    if (!isMes(g.inspecaoData, ref)) continue;
    // Pra fatura normal: só entra se g.proprietarioId === propId
    if (g.proprietarioId !== propId) continue;
    const local = locais.find(l => l.id === g.inspecaoLocalId);
    inspecoesLinhas.push({
      data: g.inspecaoData, genealogicoId: g.id,
      servicoNome: svcInspecao?.nome || 'Inspeção ABCCH',
      valorServico: valorInspecao,
      valorKm: Number(g.inspecaoKmValor) || 0,
      localNome: local?.nome || '',
      potroLabel: g.nomePotro || `${g.garanhaoNome || '—'} × ${g.eguaDoadoraNome || '—'}`,
      valor: valorInspecao + (Number(g.inspecaoKmValor) || 0),
    });
  }
  const inspecoesTotal = inspecoesLinhas.reduce((s, l) => s + l.valor, 0);

  const total = visitasTotal + insumosTotal + procedimentosTotal + avulsosTotal
    + resultadosTotal + alugueisTotal + assessoriasTotal + inspecoesTotal;

  const insumosLinhasFinais = agruparDescartaveis
    ? agruparDescartaveisLinhas(insumosLinhas, insumos)
    : insumosLinhas;

  return {
    proprietario: prop,
    ref,
    visitasLinhas, visitasTotal, visitasExcluidas,
    insumosLinhas: insumosLinhasFinais, insumosTotal,
    procedimentosLinhas, procedimentosTotal,
    avulsosLinhas, avulsosTotal,
    resultadosLinhas, resultadosTotal,
    alugueisLinhas, alugueisTotal,
    assessoriasLinhas, assessoriasTotal,
    inspecoesLinhas, inspecoesTotal,
    total,
  };
}

// ─────────────────────────────────────────────────────────────
// Nome da égua nas linhas da fatura (visitas, insumos, procedimentos e
// avulsos). Roda na tela e no PDF, tanto sobre o cálculo quanto sobre o
// snapshot de fatura fechada — as fechadas antes de 03/11/2026 não guardavam
// a égua. Só acrescenta nomes: valores e totais não mudam. Linha que já tem a
// égua (snapshot fechado depois disso) fica como está.
// Regra: a fatura só mostra nome de égua DESTE proprietário — égua de outro
// dono (no rateio da visita, doadora ou receptora) nunca aparece.
//   - Visita: éguas do proprietário com registro do mesmo vet, dia e local.
//     Lançada na fatura: as éguas escolhidas no lançamento.
//   - Descartáveis agrupados: uma linha por égua.
//   - IA/IE: o garanhão (o que vem depois do travessão na descrição) vira
//     "Garanhão × Égua". Na inovulação a égua do cruzamento é a doadora; a
//     receptora (égua do registro) vai em receptoraNome.
// ─────────────────────────────────────────────────────────────
export function comEguasNaFatura(fatura, { registros = [], cavalos = [] } = {}) {
  const propId = fatura.proprietario?.id;
  const regPorId = new Map(registros.map(r => [r.id, r]));
  const cavPorId = new Map(cavalos.map(c => [c.id, c]));
  const nomeEgua = (id) => cavPorId.get(id)?.nome || '';
  const doProp = (c) => !!c && ((c.proprietarioIds || []).includes(propId) || c.proprietarioId === propId);
  const porNome = (a, b) => a.localeCompare(b, 'pt');
  const eguaDoRegistro = (l) => nomeEgua(regPorId.get(l.registroId)?.eguaId);
  const comEgua = (l) => (l.eguaNome !== undefined ? l : { ...l, eguaNome: eguaDoRegistro(l) });

  const comEguasDaVisita = (v) => {
    if (v.eguasNomes) return v;
    if (v.manual) {
      const nomes = (v.eguasIds || []).map(id => cavPorId.get(id)).filter(doProp).map(c => c.nome);
      return { ...v, eguasNomes: nomes.filter(Boolean) };
    }
    const nomes = new Set();
    for (const r of registros) {
      if (r.vetId !== v.vetId || r.data !== v.data || r.localId !== v.localId) continue;
      const c = cavPorId.get(r.eguaId);
      if (doProp(c) && c.nome) nomes.add(c.nome);
    }
    return { ...v, eguasNomes: [...nomes].sort(porNome) };
  };

  const insumosLinhas = [];
  for (const l of (fatura.insumosLinhas || [])) {
    if (!l.agrupado || l.eguaNome !== undefined || !(l.detalhe || []).length) {
      insumosLinhas.push(comEgua(l));
      continue;
    }
    const porEgua = new Map();
    for (const d of l.detalhe.map(comEgua)) {
      if (!porEgua.has(d.eguaNome)) porEgua.set(d.eguaNome, []);
      porEgua.get(d.eguaNome).push(d);
    }
    for (const nome of [...porEgua.keys()].sort(porNome)) {
      const detalhe = porEgua.get(nome);
      insumosLinhas.push({
        ...l, eguaNome: nome, data: detalhe[0].data, detalhe,
        qtd: detalhe.reduce((s, d) => s + (Number(d.qtd) || 0), 0),
        valor: detalhe.reduce((s, d) => s + d.valor, 0),
      });
    }
  }

  const procedimentosLinhas = (fatura.procedimentosLinhas || []).map(l => {
    if (l.eguaNome !== undefined) return l;
    const garanhao = (l.descricao || '').split(' — ')[1] || '';
    if (l.tipo !== 'IE') return { ...l, garanhao, eguaNome: eguaDoRegistro(l) };
    const r = regPorId.get(l.registroId);
    const ce = r?.dados?.ceOrigemId ? regPorId.get(r.dados.ceOrigemId) : null;
    const doadora = ce ? cavPorId.get(ce.eguaId) : cavalos.find(c => c.nome === r?.dados?.eguaDoadoraNome);
    return {
      ...l, garanhao,
      eguaNome: doProp(doadora) ? doadora.nome : '',
      receptoraNome: nomeEgua(r?.eguaId),
    };
  });

  // Receptora do DG45+ (nome digitado na coleta): sai se for égua de outro dono
  const resultadosLinhas = (fatura.resultadosLinhas || []).map(l => {
    const rec = l.receptora ? cavalos.find(c => c.nome === l.receptora) : null;
    return rec && !doProp(rec) ? { ...l, receptora: null } : l;
  });

  return {
    ...fatura,
    visitasLinhas: (fatura.visitasLinhas || []).map(comEguasDaVisita),
    visitasExcluidas: (fatura.visitasExcluidas || []).map(comEguasDaVisita),
    insumosLinhas,
    procedimentosLinhas,
    avulsosLinhas: (fatura.avulsosLinhas || []).map(comEgua),
    resultadosLinhas,
  };
}

// Texto da linha com a(s) égua(s): "… — Égua"; na IA/IE com garanhão,
// "… — Garanhão × Égua".
export function textoComEgua(texto, l) {
  const eguas = l.eguasNomes || (l.eguaNome ? [l.eguaNome] : []);
  if (eguas.length === 0) return texto;
  return `${texto}${l.garanhao ? ' × ' : ' — '}${eguas.join(', ')}`;
}

// ─────────────────────────────────────────────────────────────
// Fatura externa — prospects sem cadastro no app.
//
// Processos genealógicos com proprietarioId=null mas destinatarioNome
// preenchido viram "faturas externas" agrupadas por nome. Cada fatura
// externa só tem inspeções (fonte principal de cobrança pro inspetor).
// Não gera registro na tabela de faturas; é calculada on-the-fly.
export function calcFaturasExternas(ref, deps) {
  const { servicos = [], locais = [], genealogicos = [] } = deps;
  const svcInspecao = servicos.find(s => /inspe[çc][ãa]o.*abcch|abcch.*inspe/i.test(s.nome || ''));
  const valorInspecao = Number(svcInspecao?.valor) || 0;
  // Agrupa por destinatarioNome
  const porDest = new Map();
  for (const g of (genealogicos || [])) {
    if (g.proprietarioId) continue; // só prospects
    if (!g.inspecaoFeita || !g.inspecaoData) continue;
    if (!isMes(g.inspecaoData, ref)) continue;
    const nome = (g.destinatarioNome || g.proprietarioNome || '').trim();
    if (!nome) continue;
    if (!porDest.has(nome)) porDest.set(nome, { destinatarioNome: nome, linhas: [], total: 0 });
    const bucket = porDest.get(nome);
    const local = locais.find(l => l.id === g.inspecaoLocalId);
    const linha = {
      data: g.inspecaoData, genealogicoId: g.id,
      servicoNome: svcInspecao?.nome || 'Inspeção ABCCH',
      valorServico: valorInspecao,
      valorKm: Number(g.inspecaoKmValor) || 0,
      localNome: local?.nome || '',
      potroLabel: g.nomePotro || `${g.garanhaoNome || '—'} × ${g.eguaDoadoraNome || '—'}`,
      valor: valorInspecao + (Number(g.inspecaoKmValor) || 0),
    };
    bucket.linhas.push(linha);
    bucket.total += linha.valor;
  }
  return [...porDest.values()].sort((a, b) => a.destinatarioNome.localeCompare(b.destinatarioNome, 'pt'));
}

// ─────────────────────────────────────────────────────────────
// Divisão de equipe — dado uma fatura, gera o split entre Epona e
// cada vet. Regras (pedidas pelo produto):
//   Insumos       → até 30/09/2026: 100% Epona (comprava o material)
//                 → desde 01/10/2026: 100% vet que registrou o uso
//                   (cada vet compra o próprio material; o preço segue
//                   o do cadastro de insumos)
//   Km/Visita     → 100% vet que prestou
//   IA / TE / IE  → 70% vet, 30% Epona
//   Resultado     → 50% vet inseminou, 50% Epona
//   Outros procedimentos (serviços avulsos, tratamento uterino, ozônio,
//   PRP, biópsia, cultura)
//                 → até 30/09/2026: 100% vet que fez
//                 → desde 01/10/2026: 70% vet que registrou, 30% Epona
//   Transporte    → 100% vet que registrou (Motoboy, Frete)
//   Assessoria    → só Epona interno (Alexandre/Carolina) → 100% Epona
//                 → vet externo participa → Epona 50% + externos dividem 50%
// Retorna: { epona: n, porVet: { [vetId]: n } }
// vetsExternos passado opcionalmente pra determinar interno_epona na regra
// de assessoria. Se não passar, assume que todos participantes contam
// como externos (comportamento mais conservador — não dá tudo pra Epona).
// ─────────────────────────────────────────────────────────────
export const INICIO_INSUMOS_DO_VET = '2026-10-01';
export const INICIO_PROCEDIMENTOS_70_30 = '2026-10-01';

export function dividirFatura(fatura, vetsExternos = []) {
  const acc = { epona: 0, porVet: {} };
  // Sem vet identificado vai para uma chave própria (antes era descartado e
  // a soma da divisão ficava menor que o total da fatura).
  const addVet = (vetId, v) => {
    if (!v) return;
    const k = vetId || '__sem_vet__';
    acc.porVet[k] = (acc.porVet[k] || 0) + v;
  };
  // Insumos → Epona até setembro/2026; depois, vet que registrou. Linha
  // agrupada ("Descartáveis") traz as linhas originais em `detalhe`.
  const linhasInsumo = (fatura.insumosLinhas || []).flatMap(l => (l.agrupado ? (l.detalhe || []) : [l]));
  for (const l of linhasInsumo) {
    if ((l.data || '') >= INICIO_INSUMOS_DO_VET && l.vetId !== undefined) addVet(l.vetId, l.valor);
    else acc.epona += l.valor;
  }
  // Visitas → vet
  for (const l of fatura.visitasLinhas) addVet(l.vetId, l.valor);
  // Procedimentos IA/TE → 70/30
  for (const l of fatura.procedimentosLinhas) {
    addVet(l.vetId, l.valor * 0.7);
    acc.epona += l.valor * 0.3;
  }
  // Outros procedimentos → 70/30 desde out/2026 (antes, 100% vet).
  // Transporte continua 100% vet.
  for (const l of fatura.avulsosLinhas) {
    if ((l.data || '') >= INICIO_PROCEDIMENTOS_70_30 && l.categoria !== 'transporte') {
      addVet(l.vetId, l.valor * 0.7);
      acc.epona += l.valor * 0.3;
    } else addVet(l.vetId, l.valor);
  }
  // Resultado → 50/50 (vet inseminou / Epona)
  for (const l of fatura.resultadosLinhas) {
    addVet(l.vetIdInsem, l.valor * 0.5);
    acc.epona += l.valor * 0.5;
  }
  // Assessoria clínica → regra especial.
  for (const l of (fatura.assessoriasLinhas || [])) {
    const participantes = (l.vetsParticipantes || [])
      .map(id => vetsExternos.find(v => v.id === id))
      .filter(Boolean);
    const externos = participantes.filter(v => !v.internoEpona);
    if (externos.length === 0) {
      // Só Epona interno (ou ninguém): 100% Epona
      acc.epona += l.valor;
    } else {
      // Epona 50% garantido + 50% dividido entre externos
      acc.epona += l.valor * 0.5;
      const porCada = (l.valor * 0.5) / externos.length;
      for (const v of externos) addVet(v.id, porCada);
    }
  }
  return acc;
}
